// Fonte única = Postgres/Railway. Nada de dados de negócio no localStorage.
// Estas variáveis começam vazias e são preenchidas pelo loadState() a partir do servidor.
let clientes = [];
let gruposClientes = []; // grupos editáveis de clientes (Motoristas APP, Bonificados, Diretoria...)
let faturas = [];
let recargas = [];
let parceiros = [];
let estacoes = [];
let contasReceber = []; // financeiro: recebíveis Tupi por semana (gerado das recargas)
let recebiveisManuais = []; // recebíveis lançados manualmente
let fluxoCaixa = []; // lançamentos de caixa (entradas/saídas)
