async function loadState() {
  try {
    const res = await fetch(STATE_API);
    if (res.status === 401) { window.location.href = '/login'; return; }
    if (!res.ok) throw new Error('Falha ao carregar dados do servidor');
    const data = await res.json();
    clientes = data.clientes || clientes || [];
    gruposClientes = Array.isArray(data.gruposClientes) ? data.gruposClientes : [];
    // Grupos iniciais sugeridos (só na primeira vez, editáveis depois)
    if (!gruposClientes.length) {
      gruposClientes = [
        { id: 'grp_app',    nome: 'Motoristas APP', cor: 'blue' },
        { id: 'grp_bonif',  nome: 'Bonificados',    cor: 'yellow' },
        { id: 'grp_dir',    nome: 'Diretoria',      cor: 'red' }
      ];
    }
    faturas = data.faturas || faturas || [];
    recargas = data.recargas || recargas || [];
    parceiros = data.parceiros || parceiros || [];
    estacoes = data.estacoes || estacoes || [];
    // Reidratar os mapas de ID/alias com as estações cadastradas (o mapa fixo
    // no código só cobre as estações antigas; sem isso, estações novas perdem
    // o vínculo por ID após recarregar a página)
    (estacoes || []).forEach(e => {
      const idN = String(e.idTupi || '').replace(/\D/g, '');
      if (idN) ESTACAO_ID_MAP[idN] = e.nome;
      const nLow = String(e.nome || '').toLowerCase().replace(/\s+/g, ' ').trim();
      if (nLow && !ESTACAO_ALIASES[nLow]) ESTACAO_ALIASES[nLow] = e.nome;
    });
    contasReceber = data.contasReceber || [];
    recebiveisManuais = data.recebiveisManuais || [];
    fluxoCaixa = data.fluxoCaixa || [];
    configFin = (data.configFin && Array.isArray(data.configFin.categorias)) ? data.configFin : null;
    configuracoesRede = { ...CONFIG_REDE_PADRAO, ...(data.configuracoesRede || data.configuracoes || configuracoesRede || {}) };
    estadoCarregado = true;
    try { gerarContasReceber(); } catch (e) { console.warn('gerarContasReceber:', e.message); }
    updateDashboard();
    if (typeof renderClientes === 'function') renderClientes();
    if (typeof renderFaturas === 'function') renderFaturas();
    if (typeof renderRelatorios === 'function') renderRelatorios();
    if (typeof renderParceiros === 'function') renderParceiros();
    if (typeof renderAlertasDivergenciaTupi === 'function') renderAlertasDivergenciaTupi();
    // Registrar listener do filtro de mês das estações de forma garantida
    const _mesInputEst = document.getElementById('estacoes-mes');
    if (_mesInputEst) {
      _mesInputEst.onchange = renderEstacoes;
      _mesInputEst.oninput  = renderEstacoes;
    }

    // Reparar recargas com estação inválida (ex: "Não informado")
    setTimeout(() => {
      const n = repararEstacoesInvalidas();
      if (n > 0) {
        if (typeof renderRelatorios === 'function') renderRelatorios();
        if (typeof renderEstacoes   === 'function') renderEstacoes();
      }
    }, 800);
  } catch (err) {
    console.error('Erro ao carregar dados do servidor:', err);
    estadoCarregado = false;
    if (typeof toast === 'function') {
      toast('Não foi possível carregar os dados do servidor. Recarregue a página. As alterações estão bloqueadas até reconectar para não sobrescrever dados.', 'error');
    } else {
      alert('Não foi possível carregar os dados do servidor. Recarregue a página.');
    }
  }
}

// ─── Modo somente leitura ────────────────────────────────────────────────────
let usuarioAtual = null; // { username, role }

async function carregarUsuarioAtual() {
  try {
    const res = await fetch('/api/me');
    const data = await res.json();
    usuarioAtual = data?.user || null;
    if (usuarioAtual?.role === 'leitura') ativarModoLeitura();
  } catch (e) { /* silencioso */ }
}

function isSomenteLeitura() {
  return usuarioAtual?.role === 'leitura';
}

function ativarModoLeitura() {
  document.body.classList.add('modo-leitura');
  // Faixa fixa informativa no topo
  if (!document.getElementById('faixa-leitura')) {
    const faixa = document.createElement('div');
    faixa.id = 'faixa-leitura';
    faixa.innerHTML = '👁️ <strong>Modo somente leitura</strong> — você pode visualizar tudo e gerar PDFs, mas não pode alterar dados.';
    faixa.style.cssText = 'position:sticky;top:0;z-index:9999;background:#1a2436;border-bottom:1px solid #3b82f6;color:#bfdbfe;font-size:13px;text-align:center;padding:8px 14px';
    document.body.prepend(faixa);
  }
  // Ocultar botões de ação (cosmético — a trava real está no servidor)
  const css = document.createElement('style');
  css.textContent = `
    .modo-leitura [onclick*="salvar"], .modo-leitura [onclick*="Salvar"],
    .modo-leitura [onclick*="deletar"], .modo-leitura [onclick*="excluir"], .modo-leitura [onclick*="Excluir"],
    .modo-leitura [onclick*="openModal"], .modo-leitura [onclick*="criar"], .modo-leitura [onclick*="Criar"],
    .modo-leitura [onclick*="importar"], .modo-leitura [onclick*="Importar"],
    .modo-leitura [onclick*="sync"], .modo-leitura [onclick*="corrigir"],
    .modo-leitura [onclick*="editarCampo"], .modo-leitura [onclick*="remover"],
    .modo-leitura input[type="file"], .modo-leitura .btn-danger { display: none !important; }
  `;
  document.head.appendChild(css);
}
carregarUsuarioAtual();

function saveState() {
  // Usuário somente leitura: nunca envia gravações (o servidor também bloqueia).
  if (isSomenteLeitura()) {
    console.warn('saveState ignorado: usuário somente leitura.');
    return Promise.resolve();
  }
  // Trava de segurança: se o estado ainda não foi carregado do servidor,
  // não gravamos nada para não sobrescrever o banco com dados vazios/parciais.
  if (!estadoCarregado) {
    console.warn('saveState bloqueado: estado ainda não carregado do servidor.');
    if (typeof toast === 'function') toast('Dados ainda não carregados do servidor. Recarregue a página antes de salvar.', 'error');
    return Promise.resolve();
  }
  const state = { clientes, gruposClientes, faturas, recargas, parceiros, estacoes, contasReceber, recebiveisManuais, fluxoCaixa, configFin: _getConfigFin(), configuracoesRede };
  return fetch(STATE_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(state)
  }).then(res => {
    if (res.status === 401) window.location.href = '/login';
    if (!res.ok && typeof toast === 'function') toast('Erro ao salvar no servidor.', 'error');
    return res;
  }).catch(err => {
    console.error('Erro ao salvar no servidor:', err);
    if (typeof toast === 'function') toast('Erro de conexão ao salvar. Sua alteração pode não ter sido gravada.', 'error');
  });
}


// ─────────────────────────────────────────────────────────────
//  IMPORTAÇÃO AUTOMÁTICA VIA API TUPI (OCPI)
//  As recargas sincronizadas pelo servidor (endpoint /api/tupi/recargas)
//  entram automaticamente na mesma lista de recargas, deduplicadas por uid
//  (uid = id da sessão na API = coluna "ID da Transação" do CSV). Reusa a
//  mesma lógica do import de CSV: estação pendente, parceiro, custo, cliente.
//  Sem botão — roda no load e em intervalo.
// ─────────────────────────────────────────────────────────────
let importandoAPI = false;

async function importarRecargasAPI({ silencioso = true } = {}) {
  if (!estadoCarregado || importandoAPI) return;
  importandoAPI = true;
  try {
    const res = await fetch('/api/tupi/recargas?limit=5000');
    if (!res.ok) { if (!silencioso) toast('API Tupi indisponível no momento.', 'error'); return; }
    const payload = await res.json();
    const apiRecargas = Array.isArray(payload.recargas) ? payload.recargas : [];
    if (!apiRecargas.length) return;

    // Helpers de formato (alinhados ao CSV)
    const fmtLocal = iso => {
      if (!iso) return '';
      const d = new Date(iso);
      if (isNaN(d)) return '';
      return d.toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }).slice(0, 16); // "YYYY-MM-DD HH:MM"
    };
    const fmtDur = (a, b) => {
      const ini = new Date(a), fim = new Date(b);
      if (isNaN(ini) || isNaN(fim)) return '';
      let s = Math.max(0, Math.round((fim - ini) / 1000));
      const h = Math.floor(s / 3600); s %= 3600;
      const m = Math.floor(s / 60); s %= 60;
      return `${h}h ${m}m ${s}s`;
    };

    const uidsGlobal = new Set(recargas.map(r => r.uid).filter(Boolean));
    const novas = [];

    for (const a of apiRecargas) {
      const uid = String(a.uid || a.id || '').trim();
      if (!uid) continue;
      if (uidsGlobal.has(uid)) continue; // dedup primário CSV↔API pelo id da transação

      const idEstacao  = String(a.stationId || '').trim();
      const kwh        = Number(a.kwh || 0);
      const valorTotal = Number(a.custoApiComImposto ?? a.custoApiSemImposto ?? 0);
      const email      = String(a.cliente?.email || '').toLowerCase().trim();
      const dataInicio = fmtLocal(a.dataInicio);
      const dataFim    = fmtLocal(a.dataFim);
      const duracao    = fmtDur(a.dataInicio, a.dataFim);

      // Estação: cria como pendente se ainda não existe (mesma regra do CSV).
      // A API só traz o ID da estação; o nome vem da estação já cadastrada ou
      // nasce como "Estação Tupi <id>" para você completar/renomear.
      const est = garantirEstacaoDetectada(idEstacao, a.nomeEstacao || '');
      const nomeEstacao = est?.nome || (idEstacao ? `Estação Tupi ${idEstacao}` : 'Não informado');

      // Sem RFID no caminho da API → só recarga_livre (valor 0) ou avulso_app.
      const tipoOperacao = valorTotal === 0 ? 'recarga_livre' : 'avulso_app';

      // Taxa Tupi pela estação (multi-CNPJ). A API OCPI não expõe o valor do
      // cupom, então aqui a base é o valor cobrado; se a mesma sessão vier
      // depois pelo CSV (que traz "Valor do Cupom"), o CSV corrige a taxa.
      const taxaTupiPct = getTaxaTupiPctEstacao(idEstacao, nomeEstacao);
      const taxaTupi = valorTotal * (taxaTupiPct / 100);
      const valorRec = valorTotal > 0 ? valorTotal - taxaTupi : 0;

      const _recTemp = { idEstacao, nomeEstacao, equipamento: nomeEstacao, local: nomeEstacao };
      const _nomeCanonico = normalizarEstacao(_recTemp);
      const parceiroEstacao = parceiros.find(p =>
        Array.isArray(p.equipamentos) && p.equipamentos.some(eq =>
          eq === _nomeCanonico || eq === nomeEstacao || eq === idEstacao
        )
      );
      const custoEnergiaUnit = parceiroEstacao ? Number(parceiroEstacao.custoEnergia || 0) : 0;
      const comissaoPct      = parceiroEstacao ? Number(parceiroEstacao.comissao || 0) : 0;
      const custoEnergiaTot  = kwh * custoEnergiaUnit;
      const comissaoValor    = valorRec > 0 ? (valorRec - custoEnergiaTot) * (comissaoPct / 100) : 0;
      const lucroLiquido     = valorRec - custoEnergiaTot - Math.max(0, comissaoValor);

      const clienteEmail = email ? clientes.find(c => (c.email || '').toLowerCase() === email) : null;
      const nomeCliente  = clienteEmail?.nome || a.cliente?.nome || email || 'Desconhecido';

      const rec = {
        id:             'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
        uid,
        fonte:          'api_tupi',
        idEstacao,
        local:          nomeEstacao,
        equipamento:    nomeEstacao,
        nomeEstacao,
        data:           dataInicio,
        dataFim,
        duracao,
        socInicio:      '',
        socFim:         '',
        kwh,
        cobranca:       valorTotal,
        total:          valorTotal,
        custo:          valorTotal,
        taxaTupi,
        taxaTupiPct,
        valorCupom:     0,
        saldo:          valorRec,
        rfid:           '',
        email,
        nomeCliente,
        documento:      a.cliente?.documento || '',
        tipoOperacao,
        formaPagamento: '',
        custoEnergiaTot,
        comissaoValor:  Math.max(0, comissaoValor),
        lucroLiquido,
        tarifa:         kwh > 0 ? parseFloat((valorTotal / kwh).toFixed(4)) : 0,
        importadaEm:    new Date().toISOString(),
      };

      if (recargaJaExiste(rec)) continue; // trava secundária por conteúdo
      uidsGlobal.add(uid);
      novas.push(rec);
    }

    if (!novas.length) return;

    // Auto-cadastro de clientes avulsos novos (mesma regra do CSV)
    let clientesNovos = 0;
    novas.filter(r => r.tipoOperacao === 'avulso_app' && r.cobranca > 0 && r.email).forEach(r => {
      const emailNorm = r.email.toLowerCase().trim();
      if (!clientes.find(c => (c.email || '').toLowerCase() === emailNorm)) {
        clientes.push({
          id: 'cli_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
          nome: r.nomeCliente || emailNorm, email: emailNorm, rfid: '', tipo: 'avulso',
          saldo: 0, criadoEm: new Date().toISOString(), origemImportacao: 'api_tupi',
        });
        clientesNovos++;
      }
    });

    try { detectarDivergenciasTupi?.(novas); } catch (e) { console.warn('detectarDivergenciasTupi:', e.message); }
    recargas.push(...novas);
    await saveState();
    try { await gerarFaturasAutomaticasPosPago?.(novas); } catch (e) { console.warn('gerarFaturasAutomaticasPosPago:', e.message); }

    updateDashboard?.();
    renderRelatorios?.();
    renderEstacoes?.();
    renderParceiros?.();
    if (typeof renderClientes === 'function') renderClientes();
    toast(`${novas.length} recarga(s) importada(s) automaticamente via API.${clientesNovos ? ' ' + clientesNovos + ' cliente(s) novo(s).' : ''}`, 'success');
  } catch (err) {
    console.error('Erro na importação automática via API:', err);
    if (!silencioso) toast('Erro ao importar recargas via API.', 'error');
  } finally {
    importandoAPI = false;
  }
}



function getRedeConfig() {
  return { ...CONFIG_REDE_PADRAO, ...(configuracoesRede || {}) };
}

function getContatoRede() {
  const cfg = getRedeConfig();
  return [cfg.site, cfg.telefone, cfg.email].filter(Boolean).join('  |  ');
}

function hexToRgb(hex, fallback = [0, 168, 112]) {
  const clean = String(hex || '').replace('#', '').trim();
  if (!/^[0-9a-f]{6}$/i.test(clean)) return fallback;
  return [parseInt(clean.slice(0, 2), 16), parseInt(clean.slice(2, 4), 16), parseInt(clean.slice(4, 6), 16)];
}

function addLogoPdf(doc, x, y, width = 150, height = 52) {
  const cfg = getRedeConfig();
  if (cfg.logoBase64) {
    try {
      doc.addImage(cfg.logoBase64, 'PNG', x, y, width, height);
      return true;
    } catch (err) {
      console.warn('Falha ao inserir logo no PDF:', err);
    }
  }
  const cor = hexToRgb(cfg.corPrimaria);
  doc.setTextColor(...cor);
  doc.setFontSize(22);
  doc.setFont(undefined, 'bold');
  doc.text(cfg.nomeRede || 'EV Parking', x, y + 25);
  return false;
}

