function openConfigRede() {
  garantirModalConfigRede();
  const cfg = getRedeConfig();
  ['nomeRede','subtitulo','site','telefone','email','rodapePdf'].forEach(k => {
    const el = document.getElementById('cfg-' + k);
    if (el) el.value = cfg[k] || '';
  });
  document.getElementById('cfg-corPrimaria').value = cfg.corPrimaria || '#00a870';
  document.getElementById('cfg-logo-preview').src = cfg.logoBase64 || '';
  document.getElementById('modal-config-rede').classList.add('open');
}

function carregarLogoConfigRede(input) {
  const file = input.files?.[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    configuracoesRede.logoBase64 = String(reader.result || '');
    document.getElementById('cfg-logo-preview').src = configuracoesRede.logoBase64;
  };
  reader.readAsDataURL(file);
}

function salvarConfigRede() {
  configuracoesRede = {
    ...getRedeConfig(),
    nomeRede: document.getElementById('cfg-nomeRede').value.trim() || 'EV Parking',
    subtitulo: document.getElementById('cfg-subtitulo').value.trim() || 'Rede de Eletropostos',
    site: document.getElementById('cfg-site').value.trim(),
    telefone: document.getElementById('cfg-telefone').value.trim(),
    email: document.getElementById('cfg-email').value.trim(),
    corPrimaria: document.getElementById('cfg-corPrimaria').value || '#00a870',
    rodapePdf: document.getElementById('cfg-rodapePdf').value.trim() || CONFIG_REDE_PADRAO.rodapePdf
  };
  saveState();
  closeModal('modal-config-rede');
  toast('Configurações da rede salvas com sucesso!', 'success');
}

function restaurarConfigRedePadrao() {
  if (!confirm('Restaurar dados e logo padrão da EV Parking?')) return;
  configuracoesRede = { ...CONFIG_REDE_PADRAO };
  openConfigRede();
}

function normalizarTextoChave(value = '') {
  return String(value || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function gerarRecargaUID(r) {
  const data = String(r.data || '').replace(/\s+/g, ' ').trim();
  const local = normalizarTextoChave(r.local || r.equipamento || '');
  const nome = normalizarTextoChave(r.nomeCliente || '');
  const rfid = normalizarRFID(r.rfid || '');
  const duracao = normalizarTextoChave(r.duracao || '');
  const kwh = Number(r.kwh || 0).toFixed(3);
  const cobranca = Number(r.total ?? r.cobranca ?? 0).toFixed(2);
  return [data, local, nome, rfid, duracao, kwh, cobranca].join('|');
}

function prepararRecarga(r) {
  r.uid = r.uid || gerarRecargaUID(r);
  r.importadaEm = r.importadaEm || new Date().toISOString();
  return r;
}

function recargaJaExiste(r) {
  const uid = r.uid || gerarRecargaUID(r);
  return recargas.some(x => (x.uid || gerarRecargaUID(x)) === uid);
}

function faturaAtiva(f) {
  return f &&
    !['cancelada', 'estornada', 'cancelada_sem_estorno'].includes(f.status) &&
    f.pixStatus !== 'CANCELLED' &&
    f.pixStatus !== 'REFUNDED' &&
    f.pixStatus !== 'PAID_CANCELLED_INTERNAL';
}

function recargaEmFaturaAtiva(uid) {
  return faturas.some(f => faturaAtiva(f) && Array.isArray(f.recargaUIDs) && f.recargaUIDs.includes(uid));
}

function recargaOculta(r) {
  return !!(r && (r.excluidaPendente || r.ocultaPendente || r.removidaManual));
}

function faturaDaRecargaAtiva(faturaId) {
  if (!faturaId) return false;
  const f = faturas.find(x => x.id === faturaId);
  return faturaAtiva(f);
}

function liberarRecargasFatura(f) {
  if (!f) return 0;
  const uids = new Set(f.recargaUIDs || (Array.isArray(f.recargas) ? f.recargas.map(r => r.uid || gerarRecargaUID(r)) : []));
  let liberadas = 0;
  recargas.forEach(r => {
    const ruid = r.uid || gerarRecargaUID(r);
    if ((r.faturaId === f.id) || (uids.size && uids.has(ruid))) {
      delete r.faturaId;
      liberadas++;
    }
  });
  return liberadas;
}

function fingerprintFatura(recargasLista) {
  return recargasLista.map(r => r.uid || gerarRecargaUID(r)).sort().join('||');
}


function getTipoCobrancaLabel(tipo) {
  const labels = {
    avulso: 'Avulso Tupi',
    pos: 'Pós-pago',
    pre: 'Pré-pago'
  };
  return labels[tipo || 'avulso'] || labels.avulso;
}

function getTipoCobrancaBadge(tipo) {
  const badge = tipo === 'pos' ? 'badge-yellow' : tipo === 'pre' ? 'badge-blue' : 'badge-green';
  return `<span class="badge ${badge}">${getTipoCobrancaLabel(tipo)}</span>`;
}



function normalizarRFID(rfid) {
  return String(rfid || '').trim().toLowerCase();
}

function clientePorRFID(rfid) {
  const nr = normalizarRFID(rfid);
  if (!nr) return null;
  return clientes.find(c => normalizarRFID(c.rfid) === nr) || null;
}

function clienteDaRecarga(r) {
  if (!r) return null;
  if (r.clienteId) {
    const c = clientes.find(x => x.id === r.clienteId);
    if (c) return c;
  }
  const cRfid = clientePorRFID(r.rfid);
  if (cRfid) return cRfid;
  const email = String(r.email || '').toLowerCase().trim();
  if (email) {
    const cEmail = clientes.find(x => String(x.email || '').toLowerCase().trim() === email);
    if (cEmail) return cEmail;
  }
  return null;
}

function descontoPosPagoDaRecarga(r) {
  const c = clienteDaRecarga(r);
  if (!c || c.tipo !== 'pos') return 0;
  const bruto = Number(r.cobranca ?? r.total ?? 0);
  const pct = Number(c.desconto || 0);
  return bruto > 0 && pct > 0 ? bruto * (pct / 100) : 0;
}

function valorLiquidoParceiroRecarga(r) {
  const bruto = Number(r.cobranca ?? r.total ?? 0);
  return Math.max(0, bruto - descontoPosPagoDaRecarga(r));
}

function getTipoOperacaoLabel(tipo) {
  const labels = {
    pos_pago: 'Pós-pago',
    avulso_app: 'Avulso Tupi',
    recarga_livre: 'Recarga Livre',
    desconhecido: 'Desconhecido'
  };
  return labels[tipo || 'desconhecido'] || labels.desconhecido;
}

function getTipoOperacaoBadge(tipo) {
  if (tipo === 'pos_pago')          return '<span class="badge badge-yellow">Pós-pago</span>';
  if (tipo === 'avulso_app')        return '<span class="badge badge-green">Avulso Tupi</span>';
  if (tipo === 'recarga_livre')     return '<span class="badge badge-blue">Recarga livre</span>';
  if (tipo === 'sessao_cancelada')  return '<span class="badge badge-red">Sessão cancelada</span>';
  return '<span class="badge badge-red">Desconhecido</span>';
}

function classificarRecargasPorCliente(lista = recargas) {
  lista.forEach(r => {
    if (recargaOculta(r)) return;
    prepararRecarga(r);
    const c = clientePorRFID(r.rfid);
    const clienteManual = r.faturamentoManual && r.clienteId ? clientes.find(x => x.id === r.clienteId) : null;
    r.clienteId = c?.id || clienteManual?.id || null;
    r.tipoCobranca = c?.tipo || clienteManual?.tipo || (r.tipoOperacao === 'avulso_app' ? 'avulso' : r.tipoOperacao === 'recarga_livre' ? 'livre' : 'desconhecido');
    r.faturavel = (r.tipoOperacao === 'pos_pago' && c?.tipo === 'pos') || (r.faturamentoManual && clienteManual?.tipo === 'pos');
    r.apenasConsulta = (!r.faturamentoManual && r.tipoOperacao !== 'pos_pago') || !r.faturavel;
    r.prePago = c?.tipo === 'pre';
    r.valorCobranca = Number((r.total ?? r.cobranca ?? 0).toFixed ? (r.total ?? r.cobranca ?? 0).toFixed(2) : (r.total ?? r.cobranca ?? 0));
  });
  return lista;
}

function recargaMesKey(r) {
  const dateStr = String(r.data || '');
  // Formato DD/MM/YYYY (WeMob PDF e CSV antigo)
  const partesBR = dateStr.match(/(\d{2})\/(\d{2})\/(\d{4})/);
  if (partesBR) return `${partesBR[3]}-${partesBR[2]}`;
  // Formato YYYY-MM-DD (CSV Tupi novo)
  const partesISO = dateStr.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (partesISO) return `${partesISO[1]}-${partesISO[2]}`;
  return new Date().toISOString().slice(0,7);
}

function competenciaFromMesKey(mesKey) {
  const [ano, mes] = mesKey.split('-').map(Number);
  const d = new Date(ano, mes - 1, 1);
  const txt = d.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
  return txt.charAt(0).toUpperCase() + txt.slice(1);
}

async function gerarFaturasAutomaticasPosPago(importadas = []) {
  classificarRecargasPorCliente(importadas);
  const grupos = {};
  importadas.forEach(r => {
    prepararRecarga(r);
    const uid = r.uid || gerarRecargaUID(r);
    if (faturaDaRecargaAtiva(r.faturaId) || recargaEmFaturaAtiva(uid)) return;
    const c = clientes.find(x => x.id === r.clienteId);
    if (!c || c.tipo !== 'pos') return;
    const mesKey = recargaMesKey(r);
    const key = `${c.id}_${mesKey}`;
    if (!grupos[key]) grupos[key] = { cliente: c, mesKey, fonte: r.fonte || 'importacao', recargas: [] };
    grupos[key].recargas.push(r);
  });

  let criadas = 0;
  for (const key of Object.keys(grupos)) {
    const g = grupos[key];
    const fp = fingerprintFatura(g.recargas);
    if (faturas.some(f => faturaAtiva(f) && f.clienteId === g.cliente.id && f.fingerprint === fp)) continue;
    const c = g.cliente;
    const subtotal = g.recargas.reduce((s, r) => s + (r.total ?? r.cobranca ?? 0), 0);
    const totalKwh = g.recargas.reduce((s, r) => s + (r.kwh || 0), 0);
    const descVal = subtotal * ((c.desconto || 0) / 100);
    const totalPagar = subtotal - descVal;
    const [ano, mes] = g.mesKey.split('-').map(Number);
    const venc = new Date(ano, mes, c.vencimento || 10);
    const fatura = {
      id: 'fat_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
      numero: 'EVP' + Date.now().toString().slice(-8) + String(criadas + 1).padStart(2, '0'),
      clienteId: c.id,
      recargas: g.recargas,
      competencia: competenciaFromMesKey(g.mesKey),
      vencimento: venc.toISOString(),
      totalKwh,
      subtotal,
      desconto: descVal,
      descPct: c.desconto || 0,
      totalPagar,
      pago: false,
      emitidaEm: new Date().toISOString(),
      autoImportKey: key,
      origem: 'Automática - Importação Tupi',
      status: 'emitida',
      fingerprint: fp,
      recargaUIDs: g.recargas.map(r => r.uid || gerarRecargaUID(r))
    };
    await gerarPixDaFatura(fatura, c);
    g.recargas.forEach(r => { r.faturaId = fatura.id; });
    faturas.push(fatura);
    criadas++;
  }
  if (criadas) {
    saveState();
    renderFaturas();
    updateDashboard();
    toast(`${criadas} fatura(s) pós-pago gerada(s) automaticamente.`, 'success');
  }
  return criadas;
}

// ═══════════════════════════════════════
//  NAVIGATION
// ═══════════════════════════════════════
function goTo(page) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  const screen = document.getElementById('screen-' + page);
  if (!screen) return;
  screen.classList.add('active');

  const titles = {
    dashboard:        'Dashboard Recargas',
    clientes:         'Clientes',
    parceiros:        'Parceiros',
    estacoes:         'Estações',
    payback:          'Payback',
    importar:         'Importar Tupi',
    relatorios:       'Relatórios de Recargas',
    emitir:           'Recargas Pendentes',
    faturas:          'Faturas',
    'contas-receber': 'Contas a Receber',
    'fluxo-caixa':    'Fluxo de Caixa',
    'config-fin':     'Configurações Financeiras',
  };
  document.getElementById('page-title').textContent = titles[page] || page;

  document.querySelectorAll('.nav-item').forEach(n => {
    if (n.getAttribute('onclick')?.includes(`'${page}'`)) n.classList.add('active');
  });

  const actions = document.getElementById('topbar-actions');
  actions.innerHTML = '';

  if (page === 'dashboard')  updateDashboard();
  if (page === 'clientes')   renderClientes();
  if (page === 'faturas')    renderFaturas();
  if (page === 'relatorios') {
    const mesRel = document.getElementById('relatorio-mes');
    if (mesRel && !mesRel.value) mesRel.value = getMesAtualKey();
    renderRelatorios();
  }
  if (page === 'parceiros')  renderParceiros();
  if (page === 'estacoes')   renderEstacoes();
  if (page === 'payback')    renderPayback();
  if (page === 'contas-receber') renderContasReceber();
  if (page === 'fluxo-caixa') renderFluxoCaixa();
  if (page === 'config-fin') renderConfigFin();
  if (page === 'emitir') {
    const mesPend = document.getElementById('mes-pendentes');
    if (mesPend && !mesPend.value) mesPend.value = getMesAtualKey();
    renderPendentes();
  }
}

// ═══════════════════════════════════════
//  CLIENTES
// ═══════════════════════════════════════
function openModalCliente(id = null) {
  editingClienteId = id;
  const modal = document.getElementById('modal-cliente');
  document.getElementById('modal-cliente-title').textContent = id ? 'Editar Cliente' : 'Novo Cliente';
  
  const fields = ['nome','doc','email','telefone','rfid','placa','veiculo','desconto','vencimento','tipo','saldo','pix','endereco','dataNascimento','grupoId'];
  // Popular o select de grupos antes de preencher valores
  const selGrupo = document.getElementById('c-grupoId');
  if (selGrupo) {
    selGrupo.innerHTML = '<option value="">— sem grupo —</option>'
      + gruposClientes.map(g => `<option value="${g.id}">${escapeHtml(g.nome)}</option>`).join('');
  }
  if (id) {
    const c = clientes.find(x => x.id === id);
    fields.forEach(f => document.getElementById('c-' + f).value = c[f] || '');
  } else {
    fields.forEach(f => {
      const el = document.getElementById('c-' + f);
      el.value = f === 'desconto' ? '0' : f === 'vencimento' ? '10' : f === 'tipo' ? 'avulso' : f === 'saldo' ? '0' : '';
    });
    // Auto-generate RFID suggestion
    const next = clientes.length + 1;
    document.getElementById('c-rfid').value = 'EVP-' + String(next).padStart(4,'0');
  }
  modal.classList.add('open');
}

function salvarCliente() {
  const get = id => document.getElementById('c-' + id).value.trim();
  if (!get('nome') || !get('rfid') || !get('email') || !get('doc') || !get('telefone')) {
    toast('Preencha os campos obrigatórios: Nome, CPF/CNPJ, E-mail, Telefone e RFID', 'error'); return;
  }
  const obj = {
    id: editingClienteId || 'cli_' + Date.now(),
    nome: get('nome'), doc: get('doc'), email: get('email'),
    telefone: get('telefone'), rfid: get('rfid').toUpperCase(),
    placa: get('placa').toUpperCase(), veiculo: get('veiculo'),
    desconto: parseFloat(get('desconto')) || 0,
    vencimento: parseInt(get('vencimento')) || 10,
    tipo: get('tipo') || 'avulso',
    saldo: parseFloat(get('saldo')) || 0,
    pix: get('pix'), endereco: get('endereco'),
    dataNascimento: get('dataNascimento') || '',
    grupoId: get('grupoId') || '',
    criadoEm: editingClienteId ? clientes.find(x=>x.id===editingClienteId)?.criadoEm : new Date().toISOString()
  };
  if (editingClienteId) {
    const idx = clientes.findIndex(x => x.id === editingClienteId);
    clientes[idx] = obj;
    toast('Cliente atualizado com sucesso!', 'success');
  } else {
    clientes.push(obj);
    toast('Cliente cadastrado com sucesso!', 'success');
  }
  saveState();
  closeModal('modal-cliente');
  renderClientes();
  updateDashboard();
}

function deletarCliente(id) {
  if (!confirm('Tem certeza que deseja excluir este cliente?')) return;
  clientes = clientes.filter(c => c.id !== id);
  saveState(); renderClientes(); updateDashboard();
  toast('Cliente removido.', 'success');
}

// ─── Grupos de clientes ──────────────────────────────────────────────────────
const CORES_GRUPO = ['green', 'blue', 'yellow', 'red'];

function getGrupoCliente(c) {
  return c?.grupoId ? gruposClientes.find(g => g.id === c.grupoId) || null : null;
}

function badgeGrupo(c) {
  const g = getGrupoCliente(c);
  if (!g) return '<span style="font-size:11px;color:var(--text3)">—</span>';
  return `<span class="badge badge-${g.cor || 'green'}">${escapeHtml(g.nome)}</span>`;
}

function openModalGrupos() {
  renderListaGrupos();
  document.getElementById('modal-grupos').classList.add('open');
}

function renderListaGrupos() {
  const wrap = document.getElementById('grupos-lista');
  if (!wrap) return;
  if (!gruposClientes.length) {
    wrap.innerHTML = '<div style="font-size:13px;color:var(--text3);padding:12px 0">Nenhum grupo criado ainda.</div>';
    return;
  }
  wrap.innerHTML = gruposClientes.map(g => {
    const qtd = clientes.filter(c => c.grupoId === g.id).length;
    return `
      <div style="display:flex;align-items:center;gap:10px;padding:8px 12px;background:var(--surface2);border:1px solid var(--border);border-radius:8px">
        <span class="badge badge-${g.cor || 'green'}">${escapeHtml(g.nome)}</span>
        <span style="font-size:11px;color:var(--text3);flex:1">${qtd} cliente(s)</span>
        <button class="btn btn-secondary btn-sm" onclick="renomearGrupo('${g.id}')" title="Renomear">✏️</button>
        <button class="btn btn-secondary btn-sm" onclick="trocarCorGrupo('${g.id}')" title="Trocar cor">🎨</button>
        <button class="btn btn-danger btn-sm" onclick="excluirGrupo('${g.id}')" title="Excluir">🗑️</button>
      </div>`;
  }).join('');
}

function criarGrupo() {
  const input = document.getElementById('grupo-novo-nome');
  const nome = (input?.value || '').trim();
  if (!nome) { toast('Informe o nome do grupo.', 'error'); return; }
  if (gruposClientes.some(g => g.nome.toLowerCase() === nome.toLowerCase())) {
    toast('Já existe um grupo com esse nome.', 'error'); return;
  }
  const cor = CORES_GRUPO[gruposClientes.length % CORES_GRUPO.length];
  gruposClientes.push({ id: 'grp_' + Date.now(), nome, cor });
  input.value = '';
  saveState(); renderListaGrupos(); renderClientes();
  toast('Grupo criado!', 'success');
}

function renomearGrupo(id) {
  const g = gruposClientes.find(x => x.id === id);
  if (!g) return;
  const nome = prompt('Novo nome do grupo:', g.nome);
  if (!nome || !nome.trim()) return;
  g.nome = nome.trim();
  saveState(); renderListaGrupos(); renderClientes();
}

function trocarCorGrupo(id) {
  const g = gruposClientes.find(x => x.id === id);
  if (!g) return;
  const idx = CORES_GRUPO.indexOf(g.cor || 'green');
  g.cor = CORES_GRUPO[(idx + 1) % CORES_GRUPO.length];
  saveState(); renderListaGrupos(); renderClientes();
}

function excluirGrupo(id) {
  const qtd = clientes.filter(c => c.grupoId === id).length;
  if (!confirm(`Excluir este grupo?${qtd ? ` ${qtd} cliente(s) ficarão sem grupo.` : ''}`)) return;
  gruposClientes = gruposClientes.filter(g => g.id !== id);
  clientes.forEach(c => { if (c.grupoId === id) c.grupoId = ''; });
  saveState(); renderListaGrupos(); renderClientes();
  toast('Grupo excluído.', 'success');
}

// ─── Consumo consolidado por cliente (para a tabela e rankings) ─────────────
// Vincula recargas ao cliente por clienteId, RFID ou e-mail.
function consumoDosClientes() {
  const porEmail = new Map();
  const porRfid = new Map();
  clientes.forEach(c => {
    if (c.email) porEmail.set(String(c.email).toLowerCase().trim(), c.id);
    if (c.rfid) porRfid.set(normalizarRFID(c.rfid), c.id);
  });
  const mapa = new Map(); // clienteId -> { valor, kwh, recargas, cupons, ultima }
  recargas.forEach(r => {
    if (!r || recargaOculta(r)) return;
    let cid = r.clienteId || null;
    if (!cid && r.rfid) cid = porRfid.get(normalizarRFID(r.rfid)) || null;
    if (!cid && r.email) cid = porEmail.get(String(r.email).toLowerCase().trim()) || null;
    if (!cid) return;
    const m = mapa.get(cid) || { valor: 0, kwh: 0, recargas: 0, cupons: 0, ultima: null };
    m.valor += Number(r.cobranca ?? r.total ?? 0) || 0;
    m.kwh += Number(r.kwh || 0) || 0;
    m.recargas += 1;
    m.cupons += Number(r.valorCupom || 0) || 0;
    const d = dataParaDate(r);
    if (d && (!m.ultima || d > m.ultima)) m.ultima = d;
    mapa.set(cid, m);
  });
  return mapa;
}

function fmtUltimaRecarga(d) {
  if (!d) return '<span style="color:var(--text3)">nunca</span>';
  const dias = Math.floor((Date.now() - d.getTime()) / 86400000);
  const rel = dias === 0 ? 'hoje' : dias === 1 ? 'ontem' : `há ${dias} dias`;
  return `${d.toLocaleDateString('pt-BR')} <span style="color:var(--text3)">· ${rel}</span>`;
}

function aniversarioHoje(c) {
  const s = String(c?.dataNascimento || '');
  const m = s.match(/^\d{4}-(\d{2})-(\d{2})/);
  if (!m) return false;
  const hoje = new Date();
  return Number(m[2]) === hoje.getDate() && Number(m[1]) === hoje.getMonth() + 1;
}

function renderClientes() {
  const q = (document.getElementById('search-clientes')?.value || '').toLowerCase();
  const grupoFiltro = document.getElementById('filtro-grupo-clientes')?.value || '';
  const ordem = document.getElementById('ordem-clientes')?.value || 'nome';

  // Repopular o filtro de grupos preservando a seleção
  const selFiltro = document.getElementById('filtro-grupo-clientes');
  if (selFiltro) {
    const atual = selFiltro.value;
    selFiltro.innerHTML = '<option value="">Todos os grupos</option>'
      + '<option value="__sem">Sem grupo</option>'
      + gruposClientes.map(g => `<option value="${g.id}">${escapeHtml(g.nome)}</option>`).join('');
    selFiltro.value = atual;
  }

  const consumo = consumoDosClientes();
  let filtered = clientes.filter(c =>
    String(c.nome || '').toLowerCase().includes(q) ||
    String(c.rfid || '').toLowerCase().includes(q) ||
    String(c.placa || '').toLowerCase().includes(q) ||
    String(c.email || '').toLowerCase().includes(q)
  );
  if (grupoFiltro === '__sem') filtered = filtered.filter(c => !c.grupoId);
  else if (grupoFiltro) filtered = filtered.filter(c => c.grupoId === grupoFiltro);

  const consumoDe = c => consumo.get(c.id) || { valor: 0, kwh: 0, recargas: 0, cupons: 0, ultima: null };
  if (ordem === 'consumo') filtered.sort((a, b) => consumoDe(b).valor - consumoDe(a).valor);
  else if (ordem === 'ultima') filtered.sort((a, b) => (consumoDe(b).ultima?.getTime() || 0) - (consumoDe(a).ultima?.getTime() || 0));
  else filtered.sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'));

  document.getElementById('clientes-count').textContent = `${filtered.length} cliente(s)`;
  const tbody = document.getElementById('tabela-clientes');
  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><div class="empty-icon">👤</div><div class="empty-title">Nenhum cliente encontrado</div></div></td></tr>`;
    return;
  }
  tbody.innerHTML = filtered.map(c => {
    const m = consumoDe(c);
    // 🎟️ = cliente já usou cupom mas ainda não foi classificado em grupo (sugestão)
    const marcadorCupom = (m.cupons > 0 && !c.grupoId)
      ? `<span title="Já usou R$ ${m.cupons.toFixed(2).replace('.', ',')} em cupons — classifique em um grupo" style="cursor:help">🎟️</span>` : '';
    const marcadorNiver = aniversarioHoje(c) ? '<span title="Aniversário hoje!">🎂</span>' : '';
    return `
    <tr>
      <td>
        <div style="display:flex;align-items:center;gap:10px">
          <div class="avatar avatar-green">${(c.nome || '?').charAt(0)}</div>
          <div>
            <div style="font-weight:600;font-size:13px">${escapeHtml(c.nome || '')} ${marcadorNiver} ${marcadorCupom}</div>
            <div style="font-size:11px;color:var(--text2)">${escapeHtml(c.email || '')}</div>
          </div>
        </div>
      </td>
      <td><span class="mono" style="font-size:12px;color:var(--accent)">${escapeHtml(c.rfid || '')}</span></td>
      <td><span class="mono" style="font-size:12px">${escapeHtml(c.placa || '')}</span></td>
      <td>${badgeGrupo(c)}</td>
      <td>
        <div style="font-weight:700;font-size:13px">${moneyBR(m.valor)}</div>
        <div style="font-size:11px;color:var(--text3)">${m.kwh.toFixed(1).replace('.', ',')} kWh · ${m.recargas} recarga(s)${m.cupons > 0 ? ' · 🎟️ ' + moneyBR(m.cupons) : ''}</div>
      </td>
      <td><span style="font-size:12px">${fmtUltimaRecarga(m.ultima)}</span></td>
      <td>
        <div style="display:flex;gap:6px">
          <button class="btn btn-secondary btn-sm" onclick="openModalCliente('${c.id}')">✏️</button>
          <button class="btn btn-danger btn-sm" onclick="deletarCliente('${c.id}')">🗑️</button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

// ═══════════════════════════════════════
//  FATURAS
// ═══════════════════════════════════════
function renderFaturas() {
  const tbody  = document.getElementById('tabela-faturas');
  const empty  = document.getElementById('faturas-empty');
  const q      = (document.getElementById('search-faturas')?.value || '').toLowerCase().trim();
  const dataIni = document.getElementById('filtro-data-ini')?.value || '';  // "YYYY-MM-DD"
  const dataFim = document.getElementById('filtro-data-fim')?.value || '';

  let filtered = faturas.slice().reverse();

  // Text search — match on nome, placa, rfid
  if (q) {
    filtered = filtered.filter(f => {
      const c = clientes.find(x => x.id === f.clienteId);
      const nome  = (c?.nome  || '').toLowerCase();
      const placa = (c?.placa || '').toLowerCase();
      const rfid  = (c?.rfid  || '').toLowerCase();
      return nome.includes(q) || placa.includes(q) || rfid.includes(q);
    });
  }

  // Date range filter — compare against vencimento date
  if (dataIni) {
    const ini = new Date(dataIni + 'T00:00:00');
    filtered = filtered.filter(f => new Date(f.vencimento) >= ini);
  }
  if (dataFim) {
    const fim = new Date(dataFim + 'T23:59:59');
    filtered = filtered.filter(f => new Date(f.vencimento) <= fim);
  }

  // Update count badge
  const countEl = document.getElementById('faturas-count');
  if (countEl) countEl.textContent = `${filtered.length} fatura(s) encontrada(s)`;

  if (!faturas.length) {
    tbody.innerHTML = '';
    empty.style.display = 'block';
    return;
  }
  empty.style.display = 'none';

  if (!filtered.length) {
    tbody.innerHTML = `<tr><td colspan="8"><div class="empty-state" style="padding:32px">
      <div class="empty-icon">🔍</div>
      <div class="empty-title">Nenhuma fatura encontrada</div>
      <div class="empty-sub">Tente ajustar os filtros de busca</div>
    </div></td></tr>`;
    return;
  }

  const hoje = new Date();
  tbody.innerHTML = filtered.map(f => {
    const c    = clientes.find(x => x.id === f.clienteId);
    const venc = new Date(f.vencimento);
    const estornada = f.status === 'estornada' || f.pixStatus === 'REFUNDED';
    const cancelada = estornada || f.status === 'cancelada' || f.status === 'cancelada_sem_estorno' || f.pixStatus === 'CANCELLED' || f.pixStatus === 'PAID_CANCELLED_INTERNAL';
    const status = estornada ? 'Estornada' : f.status === 'cancelada_sem_estorno' ? 'Cancelada sem estorno' : cancelada ? 'Cancelada' : f.pago ? 'Pago' : (f.pixStatus === 'ACTIVE' || f.pixStatus === 'PENDING' || f.pixStatus === 'pending') ? 'Aguardando Pix' : venc < hoje ? 'Vencida' : 'Pendente';
    const statusBadge = cancelada ? 'badge-red' : f.pago ? 'badge-green' : venc < hoje ? 'badge-red' : 'badge-yellow';
    return `
      <tr>
        <td><span class="mono" style="font-size:11px;color:var(--text2)">${f.id.slice(-8).toUpperCase()}</span></td>
        <td>
          <div style="font-weight:500">${c?.nome || 'N/A'}</div>
          <div style="font-size:11px;color:var(--text3);font-family:'DM Mono',monospace">${c?.rfid || ''} ${c?.placa ? '· ' + c.placa : ''}</div>
        </td>
        <td>${f.competencia}</td>
        <td>${venc.toLocaleDateString('pt-BR')}</td>
        <td><span class="mono">${f.totalKwh.toFixed(2)} kWh</span></td>
        <td><span class="mono" style="font-weight:600;color:var(--accent)">R$ ${f.totalPagar.toFixed(2).replace('.',',')}</span></td>
        <td><span class="badge ${statusBadge}">${status}</span></td>
        <td>
          <div style="display:flex;gap:6px">
            <button class="btn btn-secondary btn-sm" title="Visualizar" onclick="visualizarFatura('${f.id}')">👁️</button>
            <button class="btn btn-secondary btn-sm" title="Baixar PDF" onclick="downloadFaturaPDF(faturas.find(x=>x.id==='${f.id}'))">⬇️</button>
            ${!f.pago && !cancelada ? `<button class="btn btn-secondary btn-sm" title="Marcar como pago" onclick="marcarPago('${f.id}')">✅</button>` : ''}
            ${!cancelada ? `<button class="btn btn-danger btn-sm" title="Cancelar fatura" onclick="cancelarFatura('${f.id}')">🚫</button>` : ''}
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

async function cancelarFatura(id) {
  const f = faturas.find(x => x.id === id);
  if (!f) return;

  const jaPaga = !!f.pago;
  let estornar = false;

  if (jaPaga && f.pixPaymentId && f.pixProvider === 'mercadopago') {
    estornar = confirm(
      'Esta fatura já está paga.\n\nClique em OK para CANCELAR E ESTORNAR o Pix.\nClique em Cancelar para apenas cancelar no sistema, sem estorno.'
    );
  } else if (jaPaga) {
    const continuar = confirm(
      'Esta fatura está marcada como paga, mas não possui Pix Mercado Pago vinculado para estorno.\n\nDeseja cancelar apenas no sistema, sem estorno?'
    );
    if (!continuar) return;
  }

  const motivo = prompt('Motivo do cancelamento da fatura:', jaPaga ? 'Cancelamento de fatura paga' : 'Erro de emissão');
  if (motivo === null) return;

  if (!confirm(estornar ? 'Confirmar cancelamento COM ESTORNO do Pix?' : 'Confirmar cancelamento SEM estorno? As recargas ficarão liberadas para refaturamento.')) return;

  if (estornar) {
    try {
      const res = await fetch(`${PIX_API_BASE}/api/pix/estornar/${encodeURIComponent(f.pixPaymentId)}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ faturaId: f.id, motivo })
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Falha ao estornar Pix');

      f.status = 'estornada';
      f.pixStatus = 'REFUNDED';
      f.refundId = data.refundId || data.id || null;
      f.refundStatus = data.status || 'in_process';
      f.estornadaEm = new Date().toISOString();
    } catch (err) {
      toast('Não consegui estornar o Pix: ' + err.message, 'error');
      return;
    }
  } else {
    f.status = jaPaga ? 'cancelada_sem_estorno' : 'cancelada';
    f.pixStatus = jaPaga ? 'PAID_CANCELLED_INTERNAL' : 'CANCELLED';
  }

  f.canceladaEm = new Date().toISOString();
  f.motivoCancelamento = motivo || 'Não informado';

  // Libera as recargas para refaturamento, inclusive quando a fatura já estava paga/estornada.
  liberarRecargasFatura(f);

  await saveState();
  renderFaturas();
  renderRelatorios?.();
  updateDashboard();
  toast(estornar ? 'Fatura estornada e recargas liberadas para nova fatura.' : 'Fatura cancelada e recargas liberadas para nova fatura.', 'success');
}


function visualizarFatura(id) {
  const f = faturas.find(x => x.id === id);
  if (!f) { toast('Fatura não encontrada.', 'error'); return; }
  const c = clientes.find(x => x.id === f.clienteId) || {};
  renderInvoicePreview(f, c, { somenteVisualizacao: true });
  const actions = document.querySelector('#modal-fatura .modal-actions');
  if (actions) {
    actions.innerHTML = `
      <button class="btn btn-secondary" onclick="closeModal('modal-fatura')">Fechar</button>
      <button class="btn btn-primary" onclick="downloadFaturaPDF(faturas.find(x=>x.id==='${f.id}'))">⬇️ Baixar PDF</button>
    `;
  }
  document.getElementById('modal-fatura')?.classList.add('open');
}

