async function gerarPixDaFatura(f, cliente) {
  if (!f || Number(f.totalPagar || 0) <= 0) return null;
  try {
    const res = await fetch(`${PIX_API_BASE}/api/pix/cobranca`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        faturaId: f.id,
        numero: f.numero,
        valor: f.totalPagar,
        vencimento: f.vencimento,
        descricao: `Recarga EV Parking - ${f.numero || f.id}`,
        cliente: { nome: cliente?.nome, email: cliente?.email, cpfCnpj: cliente?.doc }
      })
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || 'Pix não foi gerado');
    f.pixProvider = data.provider || 'mercadopago';
    f.pixPaymentId = data.paymentId;
    f.pixTxid = data.txid;
    f.pixCopiaCola = data.payload;
    f.pixQrCodeImage = data.qrCodeImage || (data.qr_code_base64 ? `data:image/png;base64,${data.qr_code_base64}` : '');

    // Fallback: caso a API retorne apenas o Pix copia e cola,
    // o backend gera a imagem do QR Code para ser usada no PDF.
    if (!f.pixQrCodeImage && f.pixCopiaCola) {
      const qrRes = await fetch(`${PIX_API_BASE}/api/pix/qrcode`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ payload: f.pixCopiaCola })
      });
      const qrData = await qrRes.json().catch(() => ({}));
      if (qrRes.ok && qrData.qrCodeImage) f.pixQrCodeImage = qrData.qrCodeImage;
    }

    f.pixStatus = data.status || 'PENDING';
    return data;
  } catch (err) {
    toast('Pix não foi gerado: ' + err.message, 'error');
    return null;
  }
}

function salvarFaturaGerada() {
  if (!faturaRascunho) { toast('Nenhuma fatura em pré-visualização.', 'error'); return; }
  if (!faturas.some(f => f.id === faturaRascunho.id)) faturas.push(faturaRascunho);
  (faturaRascunho.recargas || []).forEach(r => {
    const real = recargas.find(x => x.id === r.id || (x.uid && x.uid === r.uid));
    if (real) real.faturaId = faturaRascunho.id;
  });
  saveState();
  closeModal('modal-fatura');
  faturaRascunho = null;
  renderFaturas();
  renderPendentes();
  updateDashboard();
  toast('Fatura salva com sucesso!', 'success');
}

function limparFiltrosFaturas() {
  const s = document.getElementById('search-faturas');
  const i = document.getElementById('filtro-data-ini');
  const f = document.getElementById('filtro-data-fim');
  const p = document.getElementById('filtro-periodo-faturas');
  if (s) s.value = '';
  if (i) i.value = '';
  if (f) f.value = '';
  if (p) p.value = '';
  renderFaturas();
}

function marcarPago(id) {
  const f = faturas.find(x => x.id === id);
  if (f) { f.pago = true; saveState(); renderFaturas(); toast('Fatura marcada como paga!','success'); }
}

// ═══════════════════════════════════════
//  CSV IMPORT & PARSING (Tupi — Transações por Lote)
// ═══════════════════════════════════════
async function handleFileSelect(input) {
  if (!input.files[0]) return;
  await processCSV(input.files[0]);
}

function handleDrop(e) {
  e.preventDefault();
  document.getElementById('upload-zone').classList.remove('drag');
  const file = e.dataTransfer.files[0];
  if (file) processCSV(file);
}

async function processCSV(file) {
  const status = document.getElementById('parse-status');
  status.style.display = 'block';
  document.getElementById('parse-filename').textContent = file.name;
  document.getElementById('parse-badge').textContent = 'Processando...';
  document.getElementById('parse-badge').className = 'badge badge-yellow';
  document.getElementById('parse-progress').style.width = '30%';
  document.getElementById('parse-content').innerHTML = '<div style="color:var(--text2);font-size:13px">Lendo arquivo CSV...</div>';

  try {
    const text = await file.text();
    document.getElementById('parse-progress').style.width = '60%';
    // Detectar formato pelo header do CSV
    const primeiraLinha = text.split(/\r?\n/)[0].replace(/"/g,'').toUpperCase();
    if (primeiraLinha.includes('E-MAIL') || primeiraLinha.includes('TOKEN DE CARGA') || primeiraLinha.includes('INÍCIO (HORÁRIO LOCAL)')) {
      await parseTupiHistoricoCSV(text, file.name);
    } else {
      await parseTupiCSV(text, file.name);
    }
  } catch (err) {
    document.getElementById('parse-badge').textContent = 'Erro';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = `<div style="color:var(--red)">Erro ao ler arquivo: ${err.message}</div>`;
  }
}

// ─────────────────────────────────────────────────────────────
//  TUPI CSV PARSER  — v1
//
//  Formato: CSV exportado em "Transações por Lote" pela plataforma Tupi
//  Colunas: ESTAÇÃO, NOME ESTAÇÃO, ENDEREÇO (ignorar), ID, DATA,
//           NOME, EMAIL, ENERGIA CONSUMIDA (kWh), VALOR TOTAL (R$),
//           VALOR PAGO (R$), DESCONTO (R$), CUPOM, TAXA DE TERCEIRO (R$),
//           TAXA TUPI (R$), DESCRIÇÃO (ignorar), VALOR A RECEBER (R$)
//
//  Regras operacionais:
//  - Cliente identificado por EMAIL
//  - RFID aparece junto ao NOME: "João Silva (a1b2c3d4)" — pós-pago
//  - NOME vazio + VALOR PAGO = 0 → sessão cancelada/falha
//  - NOME vazio + VALOR PAGO > 0 → avulso (cliente não identificado)
//  - NOME preenchido + VALOR PAGO = 0 → recarga livre
//  - VALOR A RECEBER = saldo Tupi (antes de descontar custo energia e comissão parceiro)
//  - TAXA TUPI = sempre 8%
// ─────────────────────────────────────────────────────────────

async function parseTupiCSV(csvText, filename) {
  const toNum = v => parseFloat(String(v || '0').replace(',', '.')) || 0;

  // Extrair período do nome do arquivo: Transac_o_es_por_lote__-_01-05-2026_a_31-05-2026.csv
  let periodo = '';
  const periodoMatch = filename.match(/(\d{2}-\d{2}-\d{4})_a_(\d{2}-\d{2}-\d{4})/i);
  if (periodoMatch) {
    const fmt = s => s.split('-').reverse().join('/');
    periodo = fmt(periodoMatch[1]) + ' a ' + fmt(periodoMatch[2]);
  }

  // Parse CSV respeitando campos com aspas e vírgulas internas
  function parseCSVLine(line) {
    const result = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { inQ = !inQ; }
      else if (ch === ',' && !inQ) { result.push(cur.trim()); cur = ''; }
      else { cur += ch; }
    }
    result.push(cur.trim());
    return result;
  }

  const lines = csvText.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) {
    document.getElementById('parse-badge').textContent = 'Sem dados';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = '<div style="color:var(--red)">Arquivo CSV vazio ou inválido.</div>';
    return;
  }

  const header = parseCSVLine(lines[0]).map(h => h.replace(/"/g, '').trim().toUpperCase());

  // Mapeamento flexível de colunas
  const col = name => {
    const variants = {
      'ESTACAO':      ['ESTAÇÃO', 'ESTACAO', 'ID ESTAÇÃO'],
      'NOME_ESTACAO': ['NOME ESTAÇÃO', 'NOME ESTACAO', 'NOME DA ESTAÇÃO'],
      'ID':           ['ID', 'ID DA TRANSAÇÃO', 'ID DA TRANSACAO', 'TRANSAÇÃO'],
      'DATA':         ['DATA', 'DATA/HORA', 'DATA E HORA'],
      'NOME':         ['NOME', 'NOME DO CLIENTE', 'CLIENTE'],
      'EMAIL':        ['EMAIL', 'E-MAIL'],
      'KWH':          ['ENERGIA CONSUMIDA (KWH)', 'ENERGIA (KWH)', 'KWH', 'ENERGIA'],
      'VALOR_TOTAL':  ['VALOR TOTAL (R$)', 'VALOR TOTAL', 'TOTAL (R$)'],
      'VALOR_PAGO':   ['VALOR PAGO (R$)', 'VALOR PAGO'],
      'DESCONTO':     ['DESCONTO (R$)', 'DESCONTO'],
      'CUPOM':        ['CUPOM', 'CÓDIGO CUPOM'],
      'TAXA_TERC':    ['TAXA DE TERCEIRO (R$)', 'TAXA TERCEIRO'],
      'TAXA_TUPI':    ['TAXA TUPI (R$)', 'TAXA TUPI'],
      'VALOR_REC':    ['VALOR A RECEBER (R$)', 'VALOR LÍQUIDO', 'VALOR LIQUIDO'],
    };
    const opts = variants[name] || [name];
    for (const o of opts) {
      const idx = header.indexOf(o);
      if (idx >= 0) return idx;
    }
    return -1;
  };

  const iEstacao    = col('ESTACAO');
  const iNomeEst   = col('NOME_ESTACAO');
  const iId        = col('ID');
  const iData      = col('DATA');
  const iNome      = col('NOME');
  const iEmail     = col('EMAIL');
  const iKwh       = col('KWH');
  const iTotal     = col('VALOR_TOTAL');
  const iPago      = col('VALOR_PAGO');
  const iDesconto  = col('DESCONTO');
  const iCupom     = col('CUPOM');
  const iTaxaTerc  = col('TAXA_TERC');
  const iTaxaTupi  = col('TAXA_TUPI');
  const iValorRec  = col('VALOR_REC');

  // Função: parsear data do formato "de dd/mm/aaaa HH:MM até dd/mm/aaaa HH:MM"
  // Retorna { dataInicio, dataFim, duracao }
  function parseDuracao(raw) {
    const m = String(raw || '').match(/de\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})\s+at[eé]\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})/i);
    if (!m) return { dataInicio: raw, dataFim: '', duracao: '' };
    const [, d1, h1, d2, h2] = m;
    // Calcular duração
    const toMs = (d, h) => {
      const [dd, mm, yyyy] = d.split('/').map(Number);
      const [hh, mi] = h.split(':').map(Number);
      return new Date(yyyy, mm - 1, dd, hh, mi).getTime();
    };
    const diffMs = toMs(d2, h2) - toMs(d1, h1);
    const diffMin = Math.max(0, Math.round(diffMs / 60000));
    const durHoras = Math.floor(diffMin / 60);
    const durMins  = diffMin % 60;
    const duracao  = diffMin > 0
      ? (durHoras > 0 ? `${durHoras}h ${String(durMins).padStart(2,'0')}min` : `${durMins}min`)
      : '—';
    return { dataInicio: `${d1} ${h1}`, dataFim: `${d2} ${h2}`, duracao };
  }

  // Função: extrair nome e RFID do campo NOME
  // "João Silva (a1b2c3d4)" → { nome: "João Silva", rfid: "a1b2c3d4" }
  function extrairNomeRFID(raw) {
    const s = String(raw || '').trim();
    const m = s.match(/^(.+?)\s*\(([0-9a-fA-F]{6,30})\)\s*$/);
    if (m) return { nome: m[1].trim(), rfid: normalizarRFID(m[2]) };
    return { nome: s, rfid: '' };
  }

  // Função: determinar local e equipamento a partir do NOME ESTAÇÃO
  // "M7 Mafra EV Parking 40kW DC" → local: "M7 Mafra EV Parking", equip: "40kW DC"
  // "Lefel 40kW DC" → local: "Lefel", equip: "40kW DC"
  function parsearEstacao(nomeEstacao, idEstacao) {
    const n = String(nomeEstacao || '').trim();
    // Separar potência do local
    const mPot = n.match(/^(.+?)\s+([\d,]+kW(?:\s*\w+)?)\s*$/i);
    if (mPot) return { local: mPot[1].trim(), equipamento: mPot[2].trim(), nomeCompleto: n, idEstacao: String(idEstacao || '') };
    return { local: n, equipamento: n, nomeCompleto: n, idEstacao: String(idEstacao || '') };
  }

  const novas = [];

  for (let i = 1; i < lines.length; i++) {
    const cols = parseCSVLine(lines[i]);
    if (cols.length < 4) continue;

    const get = idx => idx >= 0 && idx < cols.length ? cols[idx].replace(/"/g, '').trim() : '';

    const idEstacao   = get(iEstacao);
    const nomeEstacao = get(iNomeEst);
    const idTrans     = get(iId);
    const dataRaw     = get(iData);
    const nomeRaw     = get(iNome);
    const email       = get(iEmail).toLowerCase();
    const kwh         = toNum(get(iKwh));
    const valorTotal  = toNum(get(iTotal));
    const valorPago   = toNum(get(iPago));
    const desconto    = toNum(get(iDesconto));
    const cupom       = get(iCupom).replace(/^\s*-\s*$/, '').trim();
    const taxaTerc    = toNum(get(iTaxaTerc));
    const taxaTupi    = toNum(get(iTaxaTupi));
    const valorRec    = toNum(get(iValorRec));

    if (!idTrans && !nomeEstacao) continue; // linha vazia

    const { dataInicio, dataFim, duracao } = parseDuracao(dataRaw);
    const { nome: nomeCliente, rfid } = extrairNomeRFID(nomeRaw);
    const { local, equipamento, nomeCompleto, idEstacao: estId } = parsearEstacao(nomeEstacao, idEstacao);

    // Determinar tipo de operação
    // sessao_cancelada: kwh=0 e valorPago=0 (cliente presente mas não carregou)
    // recarga_livre: tem nome mas valorPago=0 e kwh>0, ou marcado como livre
    // pos_pago: tem rfid cadastrado (cobrança via fatura)
    // avulso_app: pagou direto pelo app (sem rfid)
    let tipoOperacao;
    if (kwh === 0 && valorPago === 0) {
      tipoOperacao = 'sessao_cancelada';
    } else if (rfid) {
      tipoOperacao = 'pos_pago';
    } else if (valorPago === 0 && kwh > 0) {
      tipoOperacao = 'recarga_livre';
    } else {
      tipoOperacao = 'avulso_app';
    }

    // Buscar parceiro pela estação — usar nome canônico normalizado como critério único
    const _recTemp = { idEstacao: estId, nomeEstacao: nomeCompleto, equipamento, local: equipamento };
    const _nomeCanonicoTemp = normalizarEstacao(_recTemp);
    const parceiroEstacao = parceiros.find(p =>
      (Array.isArray(p.equipamentos) && p.equipamentos.some(eq =>
        eq === _nomeCanonicoTemp || eq === nomeCompleto || eq === equipamento || eq === estId
      ))
    );
    const custoEnergiaUnit = parceiroEstacao ? Number(parceiroEstacao.custoEnergia || 0) : 0;
    const comissaoPct      = parceiroEstacao ? Number(parceiroEstacao.comissao || 0) : 0;
    const custoEnergiaTot  = kwh * custoEnergiaUnit;
    const comissaoValor    = valorRec > 0 ? (valorRec - custoEnergiaTot) * (comissaoPct / 100) : 0;
    const lucroLiquido     = valorRec - custoEnergiaTot - Math.max(0, comissaoValor);

    // Se aparecer uma estação nova no relatório, cadastrar como pendente para ela ficar disponível no módulo Estações.
    garantirEstacaoDetectada(estId, nomeCompleto || equipamento || local);

    novas.push({
      id:            'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      uid:           idTrans, // ID Tupi como chave de deduplicação
      idTrans,
      idEstacao:     estId,
      local,
      equipamento,
      nomeEstacao:   nomeCompleto,
      nomeCliente:   nomeCliente || '',
      email,
      rfid,
      tipoOperacao,
      data:          dataInicio,
      dataFim,
      duracao,
      kwh,
      tarifa:        kwh > 0 ? parseFloat((valorTotal / kwh).toFixed(4)) : 0,
      custo:         valorTotal,   // valor bruto
      total:         valorTotal,   // valor total da sessão (usado para faturar recargas livres vinculadas)
      cobranca:      valorPago,    // valor cobrado/pago
      desconto,
      cupom,
      taxaTerceiro:  taxaTerc,
      taxaTupi,                    // 8% explícito
      saldo:         valorRec,     // valor a receber da Tupi
      lucroLiquido,                // saldo − custo energia − comissão parceiro
      custoEnergiaTot,
      comissaoValor,
      fonte:         filename,
      periodo,
    });
  }

  document.getElementById('parse-progress').style.width = '90%';

  if (novas.length > 0) {
    classificarRecargasPorCliente(novas);

    const novasUnicas = [];
    const duplicadas  = [];
    const uidsVistos  = new Set();
    let confirmadas = 0;
    novas.forEach(r => {
      prepararRecarga(r);
      r.confirmadoTupi = true; // veio do relatório oficial "Transações por lote" (valores exatos)
      const uid = r.uid || r.idTrans || gerarRecargaUID(r);
      if (uidsVistos.has(uid)) { duplicadas.push(r); return; }
      uidsVistos.add(uid);
      // Se a recarga já existe (veio antes pela API/histórico com valores estimados),
      // ATUALIZA com os valores exatos do relatório e marca como confirmada.
      const existente = recargas.find(x => (x.uid || gerarRecargaUID(x)) === uid);
      if (existente) {
        existente.total        = r.total;
        existente.custo        = r.custo;
        existente.cobranca     = r.cobranca;
        existente.desconto     = r.desconto;
        existente.cupom        = r.cupom;
        existente.taxaTupi     = r.taxaTupi;
        existente.taxaTerceiro = r.taxaTerceiro;
        existente.saldo        = r.saldo; // VALOR A RECEBER exato
        existente.confirmadoTupi = true;
        existente.fonteConfirmacao = r.fonte;
        confirmadas++;
        duplicadas.push(r);
      } else {
        novasUnicas.push(r);
      }
    });

    detectarDivergenciasTupi(novas);
    if (novasUnicas.length) {
      recargas = [...recargas, ...novasUnicas];
      classificarRecargasPorCliente(recargas);

      // Auto-cadastrar clientes Avulso Tupi pagos (email + valor > 0)
      let clientesNovos = 0;
      novasUnicas
        .filter(r => r.tipoOperacao === 'avulso_app' && r.cobranca > 0 && r.email)
        .forEach(r => {
          const emailNorm = r.email.toLowerCase().trim();
          const jaExiste = clientes.find(c => (c.email || '').toLowerCase() === emailNorm);
          if (!jaExiste) {
            clientes.push({
              id:        'cli_avulso_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
              nome:      r.nomeCliente || emailNorm,
              email:     emailNorm,
              doc:       '',
              telefone:  '',
              rfid:      '',
              placa:     '',
              veiculo:   '',
              desconto:  0,
              vencimento: 10,
              tipo:      'avulso',
              saldo:     0,
              pix:       '',
              endereco:  '',
              criadoEm:  new Date().toISOString(),
              origemImportacao: 'tupi_csv'
            });
            clientesNovos++;
          }
        });

      try { gerarContasReceber(); } catch (e) { console.warn('gerarContasReceber:', e.message); }
      saveState();
      if (clientesNovos > 0) toast(clientesNovos + ' cliente(s) Avulso Tupi cadastrado(s) automaticamente.', 'success');
    }

    document.getElementById('parse-progress').style.width = '100%';
    document.getElementById('parse-badge').textContent = `${novasUnicas.length} novas / ${confirmadas} confirmadas`;
    document.getElementById('parse-badge').className = (novasUnicas.length || confirmadas) ? 'badge badge-green' : 'badge badge-yellow';
    renderParseResult(novasUnicas.length ? novasUnicas : novas, periodo);
    renderRelatorios?.();
    if (typeof renderContasReceber === 'function' && document.getElementById('screen-contas-receber')?.classList.contains('active')) renderContasReceber();
    toast(`${novasUnicas.length} nova(s) e ${confirmadas} confirmada(s) pelo relatório oficial da Tupi.`, 'success');
  } else {
    document.getElementById('parse-progress').style.width = '100%';
    document.getElementById('parse-badge').textContent = 'Sem dados';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = `
      <div style="color:var(--red);font-size:13px;margin-bottom:8px">
        ⚠️ Não foi possível extrair recargas do CSV.<br>
        Verifique se o arquivo é um relatório <strong>Transações por Lote</strong> ou <strong>Histórico de Cargas</strong> da Tupi.
      </div>
      <div style="background:var(--surface2);border-radius:8px;padding:12px;font-size:11px;font-family:'DM Mono',monospace;color:var(--text2);margin-bottom:12px;word-break:break-all;max-height:150px;overflow:auto">
        ${csvText.slice(0, 600)}
      </div>
    `;
  }
}


// ─────────────────────────────────────────────────────────────
//  TUPI CSV PARSER — Histórico de Cargas (formato novo)
//
//  Formato: CSV exportado em "Histórico de Cargas" pela plataforma Tupi
//  Separador: vírgula, campos entre aspas
//  Colunas-chave:
//    E-mail, Estação, ID, ID da Transação,
//    Energia em kWh, Valor Total, Forma de Pagamento,
//    Token de Carga (= RFID quando pós-pago),
//    Início (Horário Local), Fim (Horário Local),
//    SoC inicial, SoC final, Duração
//
//  Diferenças em relação ao "Transações por Lote":
//  - Separador é vírgula (não ponto-e-vírgula)
//  - Não tem coluna NOME separada do email
//  - Não tem VALOR A RECEBER nem TAXA TUPI explícita
//  - Datas no formato DD/MM/YYYY HH:MM:SS
//  - Token de Carga = RFID (quando pós-pago)
// ─────────────────────────────────────────────────────────────

async function parseTupiHistoricoCSV(csvText, filename) {
  // Extrair período do nome do arquivo
  let periodo = '';
  const mPer = filename.match(/(\d{2})[_-](\d{2})[_-](\d{4}).*?(\d{2})[_-](\d{2})[_-](\d{4})/i);
  if (mPer) periodo = `${mPer[1]}/${mPer[2]}/${mPer[3]} a ${mPer[4]}/${mPer[5]}/${mPer[6]}`;

  // Parse CSV RFC 4180 (separador: vírgula, campos entre aspas)
  function parseCSVLine(line) {
    const result = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQ && line[i+1] === '"') { cur += '"'; i++; }
        else inQ = !inQ;
      } else if (ch === ',' && !inQ) {
        result.push(cur); cur = '';
      } else {
        cur += ch;
      }
    }
    result.push(cur);
    return result.map(s => s.trim());
  }

  function toNum(s) {
    return parseFloat(String(s || '0').replace(/\./g,'').replace(',','.')) || 0;
  }

  function parsearDataLocal(s) {
    // "07/05/2026 21:39:16" → "2026-05-07 21:39"
    const m = String(s || '').match(/(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}:\d{2})/);
    if (m) return `${m[3]}-${m[2]}-${m[1]} ${m[4]}`;
    return s || '';
  }

  const lines = csvText.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) {
    document.getElementById('parse-badge').textContent = 'Sem dados';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = '<div style="color:var(--red)">Arquivo CSV vazio ou inv\u00E1lido.</div>';
    return;
  }

  // Mapear colunas dinamicamente — comparar sem acentos para robustez
  const normalize = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().trim();
  const header = parseCSVLine(lines[0]).map(h => normalize(h.replace(/"/g,'')));

  function col(aliases) {
    for (const a of aliases) {
      const i = header.indexOf(normalize(a));
      if (i !== -1) return i;
    }
    return -1;
  }

  const iEmail      = col(['E-MAIL', 'EMAIL']);
  const iEstacao    = col(['ESTACAO', 'ESTACAO']);
  const iId         = col(['ID']);
  const iIdTrans    = col(['ID DA TRANSACAO']);
  const iKwh        = col(['ENERGIA EM KWH']);
  const iValorTotal = col(['VALOR TOTAL']);
  const iValorCupom = col(['VALOR DO CUPOM']);
  const iFormaPag   = col(['FORMA DE PAGAMENTO']);
  const iToken      = col(['TOKEN DE CARGA']);
  const iInicio     = col(['INICIO (HORARIO LOCAL)']);
  const iFim        = col(['FIM (HORARIO LOCAL)']);
  const iSocIni     = col(['SOC INICIAL']);
  const iSocFin     = col(['SOC FINAL']);
  const iDuracao    = col(['DURACAO']);

  if (iEmail === -1 || iIdTrans === -1 || iKwh === -1) {
    document.getElementById('parse-badge').textContent = 'Formato inv\u00E1lido';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = `
      <div style="color:var(--red);font-size:13px;margin-bottom:8px">
        &#x26A0;&#xFE0F; N\u00E3o foi poss\u00EDvel extrair recargas do CSV.<br>
        Verifique se o arquivo \u00E9 um relat\u00F3rio <strong>Hist\u00F3rico de Cargas</strong> da Tupi.
      </div>
      <div style="background:var(--surface2);border-radius:8px;padding:12px;font-size:11px;font-family:'DM Mono',monospace;color:var(--text2);margin-bottom:12px;word-break:break-all;max-height:150px;overflow:auto">
        ${csvText.slice(0, 600)}
      </div>
    `;
    return;
  }

  const novas = [];
  const uidsVistos = new Set();

  for (let i = 1; i < lines.length; i++) {
    const cols = parseCSVLine(lines[i]);
    const get  = idx => (idx !== -1 && cols[idx] != null) ? cols[idx].trim() : '';

    const idTrans     = String(get(iIdTrans)).replace(/[^\w]/g,'');
    const nomeEstacao = get(iEstacao);
    const idEstacao   = get(iId);
    const email       = get(iEmail).toLowerCase();
    const kwh         = toNum(get(iKwh));
    const valorTotal  = toNum(get(iValorTotal));
    const valorCupom  = toNum(get(iValorCupom));   // desconto do cupom (Tupi cobra taxa sobre o bruto)
    const formaPag    = get(iFormaPag);
    const token       = get(iToken).trim();
    const dataInicio  = parsearDataLocal(get(iInicio));
    const dataFim     = parsearDataLocal(get(iFim));
    const socIni      = get(iSocIni);
    const socFin      = get(iSocFin);
    const duracao     = get(iDuracao);

    if (!idTrans || !nomeEstacao) continue;
    if (uidsVistos.has(idTrans)) continue;
    uidsVistos.add(idTrans);

    // Token de carga = RFID quando pós-pago
    const rfid = (token && token !== ' ' && token !== '---') ? normalizarRFID(token) : '';

    // Tipo de operação
    let tipoOperacao;
    if (rfid && clientePorRFID(rfid))    tipoOperacao = 'pos_pago';
    else if (valorTotal === 0)           tipoOperacao = 'recarga_livre';
    else                                 tipoOperacao = 'avulso_app';

    // Taxa Tupi: percentual da estação (multi-CNPJ), sobre o valor BRUTO da
    // sessão (valor cobrado + cupom) — a Tupi não desconta cupons da base.
    const taxaTupiPct  = getTaxaTupiPctEstacao(idEstacao, nomeEstacao);
    const taxaTupi     = (valorTotal + valorCupom) * (taxaTupiPct / 100);
    const valorRec     = valorTotal > 0 ? valorTotal - taxaTupi : 0;

    // Buscar parceiro pelo nome canônico da estação
    const _recTemp = { idEstacao, nomeEstacao, equipamento: nomeEstacao, local: nomeEstacao };
    const _nomeCanonico = normalizarEstacao(_recTemp);
    const parceiroEstacao = parceiros.find(p =>
      Array.isArray(p.equipamentos) && p.equipamentos.some(eq =>
        eq === _nomeCanonico || eq === nomeEstacao || eq === idEstacao
      )
    );
    const custoEnergiaUnit = parceiroEstacao ? Number(parceiroEstacao.custoEnergia || 0) : 0;
    const comissaoPct      = parceiroEstacao ? Number(parceiroEstacao.comissao || 0) : 0;
    const custoEnergiaTot  = kwh * custoEnergiaUnit;
    const comissaoValor    = valorRec > 0 ? (valorRec - custoEnergiaTot) * (comissaoPct / 100) : 0;
    const lucroLiquido     = valorRec - custoEnergiaTot - Math.max(0, comissaoValor);

    // Resolver nome do cliente pelo e-mail
    const clienteEmail = clientes.find(c => (c.email || '').toLowerCase() === email);
    const nomeCliente  = clienteEmail?.nome || email || 'Desconhecido';

    // Se aparecer uma estação nova no relatório, cadastrar como pendente para ela ficar disponível no módulo Estações.
    garantirEstacaoDetectada(idEstacao, nomeEstacao);

    novas.push({
      id:             'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      uid:            idTrans,
      fonte:          'historico_tupi',
      idEstacao,
      local:          nomeEstacao,
      equipamento:    nomeEstacao,
      nomeEstacao,
      data:           dataInicio,
      dataFim,
      duracao,
      socInicio:      socIni !== '---' ? socIni : '',
      socFim:         socFin !== '---' ? socFin : '',
      kwh,
      cobranca:       valorTotal,
      total:          valorTotal,
      custo:          valorTotal,
      taxaTupi,
      taxaTupiPct,
      valorCupom,
      saldo:          valorRec,
      rfid,
      email,
      nomeCliente,
      tipoOperacao,
      formaPagamento: formaPag,
      custoEnergiaTot,
      comissaoValor:  Math.max(0, comissaoValor),
      lucroLiquido,
      tarifa:         kwh > 0 ? parseFloat((valorTotal / kwh).toFixed(4)) : 0,
      importadaEm:    new Date().toISOString(),
    });
  }

  document.getElementById('parse-progress').style.width = '90%';

  if (novas.length) {
    // Auto-cadastrar clientes avulsos novos
    let clientesNovos = 0;
    novas
      .filter(r => r.tipoOperacao === 'avulso_app' && r.cobranca > 0 && r.email)
      .forEach(r => {
        const emailNorm = r.email.toLowerCase().trim();
        const jaExiste  = clientes.find(c => (c.email || '').toLowerCase() === emailNorm);
        if (!jaExiste) {
          clientes.push({
            id:    'cli_' + Date.now() + '_' + Math.random().toString(36).slice(2,8),
            nome:  r.nomeCliente || emailNorm,
            email: emailNorm,
            rfid:  '',
            tipo:  'avulso',
            saldo: 0,
            criadoEm:         new Date().toISOString(),
            origemImportacao: 'historico_tupi',
          });
          clientesNovos++;
        }
      });
    if (clientesNovos > 0) toast(clientesNovos + ' cliente(s) cadastrado(s) automaticamente.', 'success');

    const uidsGlobal   = new Set(recargas.map(r => r.uid).filter(Boolean));
    const novasUnicas  = novas.filter(r => !uidsGlobal.has(r.uid) && !recargaJaExiste(r));
    const duplicadas   = novas.filter(r =>  uidsGlobal.has(r.uid) ||  recargaJaExiste(r));

    // Corrigir cupom/taxa das recargas que já existiam (importadas antes pela
    // API, que não expõe o "Valor do Cupom"): o CSV traz o dado exato, então a
    // taxa Tupi é recalculada sobre o bruto (valor + cupom). Só esses campos
    // são tocados — valores editados manualmente permanecem intactos.
    let taxasCorrigidas = 0;
    duplicadas.forEach(d => {
      const existente = recargas.find(x => (x.uid || gerarRecargaUID(x)) === d.uid);
      if (!existente) return;
      const cupomNovo = Number(d.valorCupom || 0);
      const pctNovo   = Number(d.taxaTupiPct || 0) || getTaxaTupiPctEstacao(existente.idEstacao, normalizarEstacao(existente));
      const taxaNova  = (Number(existente.cobranca ?? existente.total ?? existente.custo ?? 0) + cupomNovo) * (pctNovo / 100);
      const mudou = Number(existente.valorCupom || 0) !== cupomNovo
        || Number(existente.taxaTupiPct || 0) !== pctNovo
        || Math.abs(Number(existente.taxaTupi || 0) - taxaNova) >= 0.005;
      if (mudou) {
        existente.valorCupom  = cupomNovo;
        existente.taxaTupiPct = pctNovo;
        existente.taxaTupi    = taxaNova;
        taxasCorrigidas++;
      }
    });
    if (taxasCorrigidas > 0) toast(`${taxasCorrigidas} recarga(s) com cupom/taxa Tupi corrigidos pelo CSV.`, 'success');

    detectarDivergenciasTupi(novas);
    recargas.push(...novasUnicas);
    saveState();

    document.getElementById('parse-progress').style.width = '100%';
    document.getElementById('parse-badge').textContent = `${novasUnicas.length} novas / ${duplicadas.length} duplicadas`;
    document.getElementById('parse-badge').className = novasUnicas.length ? 'badge badge-green' : 'badge badge-yellow';
    renderParseResult(novasUnicas.length ? novasUnicas : novas, periodo);
    await gerarFaturasAutomaticasPosPago(novasUnicas);
    renderRelatorios?.();
    toast(`${novasUnicas.length} recargas novas importadas. ${duplicadas.length} duplicada(s) ignorada(s).`, novasUnicas.length ? 'success' : 'error');
  } else {
    document.getElementById('parse-badge').textContent = 'Sem dados';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = `
      <div style="color:var(--red);font-size:13px;margin-bottom:8px">
        &#x26A0;&#xFE0F; N\u00E3o foi poss\u00EDvel extrair recargas do CSV.<br>
        Verifique se o arquivo \u00E9 um <strong>Hist\u00F3rico de Cargas</strong> da Tupi.
      </div>
      <div style="background:var(--surface2);border-radius:8px;padding:12px;font-size:11px;font-family:'DM Mono',monospace;color:var(--text2);margin-bottom:12px;word-break:break-all;max-height:150px;overflow:auto">
        ${csvText.slice(0, 600)}
      </div>
    `;
  }
}

// Stub vazio — mantido por compatibilidade com gerarFaturasAutomaticasPosPago
function parseWemobPlainText(plainText, filename, periodo) {
  const novas = [];
  const text = String(plainText || '').replace(/\s+/g, ' ').trim();
  const stationRe = /^(?:.*?\s)?P[uú]blica\s+(M7\s+Mafra\s+EV\s+Parking\s+40kW\s+DC|M7\s+Mafra\s+EV\s+Parking\s+22kW\s+AC|Lefel\s+40kW\s+DC|Lefel\s+46kW(?:\s+AC)?)\s+(.+)$/i;
  const toNum = v => parseFloat(String(v).replace(',', '.')) || 0;

  // Divide em blocos por recarga. É mais estável que depender da posição X/Y do PDF.
  const blocos = text
    .split(/\s+(?=P[uú]blica\s+(?:M7\s+Mafra|Lefel))/i)
    .filter(b => /P[uú]blica\s+(?:M7\s+Mafra|Lefel)/i.test(b));

  blocos.forEach(blocoOriginal => {
    let bloco = blocoOriginal.replace(/\s+Totalizador das recargas:.+$/i, '').trim();
    bloco = bloco.replace(/\s+Gerado no dia\s+\d{2}\/\d{2}\/\d{4}.+$/i, '').trim();

    const dt = bloco.match(/(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})\s+(\d{1,2}h\s*\d{1,2}min(?:\s*\d{1,2}s)?)\s+(-?\d{1,4}[,.]\d{2})\s+((?:\d{1,3}\s*-\s*\d{1,3})|-)\s+(-?\d{1,4}[,.]\d{2})\s+(-?\d{1,4}[,.]\d{2})\s+(-?\d{1,4}[,.]\d{2})/i);
    if (!dt) return;

    const beforeDate = bloco.slice(0, dt.index).trim();
    const sm = beforeDate.match(stationRe);
    if (!sm) return;

    const local = 'Pública ' + sm[1].replace(/\s+/g, ' ').trim();
    let rawName = sm[2].replace(/\s+/g, ' ').trim();
    rawName = rawName.replace(/^(Relat[óo]rios|Per[ií]odo).+?\s+/i, '').trim();
    if (!rawName || /^(Hor[aá]rio|Dura[cç][aã]o|Energia|SoC|Custo|Cobran[cç]a|Saldo)$/i.test(rawName)) return;

    let nomeCliente = rawName;
    let rfid = '';
    const rfidMatch = rawName.match(/^(.+?)\s*\(([0-9a-f]{6,20})\)\s*$/i);
    if (rfidMatch) {
      nomeCliente = rfidMatch[1].trim();
      rfid = normalizarRFID(rfidMatch[2]);
    }

    const tipoOperacao = /^Recarga Livre$/i.test(nomeCliente)
      ? 'recarga_livre'
      : (rfid ? 'pos_pago' : 'avulso_app');

    const kwh = toNum(dt[4]);
    const custo = toNum(dt[6]);
    const cobranca = toNum(dt[7]);
    const saldo = toNum(dt[8]);
    const soc = dt[5] === '-' ? '-' : String(dt[5]).replace(/\s+/g, ' ') + '%';

    novas.push({
      id: 'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      rfid,
      nomeCliente,
      tipoOperacao,
      data: dt[1] + ' ' + dt[2],
      local,
      duracao: String(dt[3]).replace(/\s+/g, ' ').trim(),
      soc,
      kwh,
      tarifa: kwh > 0 ? parseFloat((custo / kwh).toFixed(4)) : 0,
      custo,
      cobranca,
      saldo,
      total: cobranca,
      fonte: filename,
      periodo
    });
  });

  return novas;
}

async function parseWemob(items, plainText, filename) {
  let periodo = '';
  const periodoMatch = plainText.match(/Per[ií]odo[:\s]+([\d\/]+)\s+at[eé]\s+([\d\/]+)/i);
  if (periodoMatch) periodo = periodoMatch[1] + ' a ' + periodoMatch[2];

  const toNum = v => parseFloat(String(v || '0').replace(',', '.')) || 0;
  const novas = [];

  // Parser oficial da Rede para relatório Tupi em 3 linhas por recarga:
  // Linha A: Pública + data + duração + kWh + SoC + custo + cobrança + saldo
  // Linha B: Equipamento/estação + hora
  // Linha C: Nome do cliente ou Nome (RFID) ou Recarga Livre
  const rowMap = [];
  (items || []).forEach(item => {
    if (!item.str || !String(item.str).trim()) return;
    const page = item.page || 1;
    const existing = rowMap.find(r => r.page === page && Math.abs(r.y - item.y) <= 6);
    if (existing) existing.items.push(item);
    else rowMap.push({ page, y: item.y, items: [item] });
  });

  rowMap.sort((a, b) => (a.page - b.page) || (b.y - a.y));

  const rows = rowMap.map(r => {
    r.items.sort((a, b) => a.x - b.x);
    return {
      page: r.page,
      y: r.y,
      full: r.items.map(i => String(i.str).trim()).filter(Boolean).join(' ').replace(/\s+/g, ' ').trim()
    };
  }).filter(r => r.full);

  for (let i = 0; i < rows.length - 2; i++) {
    const rowA = rows[i];
    const rowB = rows[i + 1];
    const rowC = rows[i + 2];

    if (rowA.page !== rowB.page || rowA.page !== rowC.page) continue;
    if (!/^P[uú]blica\b/i.test(rowA.full)) continue;
    if (/Totalizador|Gerado no dia|Per[ií]odo|Hor[aá]rio/i.test(rowA.full)) continue;

    const dateMatch = rowA.full.match(/(\d{2}\/\d{2}\/\d{4})/);
    const timeMatch = rowB.full.match(/(\d{2}:\d{2})/);
    const durMatch = rowA.full.match(/(\d{1,2}h\s*\d{1,2}min(?:\s*\d{1,2}s)?)/i);
    if (!dateMatch || !timeMatch || !durMatch) continue;

    const station = rowB.full.replace(/\b\d{2}:\d{2}\b/g, '').replace(/\s+/g, ' ').trim();
    if (!station || /^(P[uú]blica|Hor[aá]rio|Totalizador)/i.test(station)) continue;

    let rawName = rowC.full.replace(/\s+/g, ' ').trim();
    if (!rawName || /^(P[uú]blica|Lefel|M7\s|Totalizador|Gerado no dia|Per[ií]odo|Hor[aá]rio|\d)/i.test(rawName)) continue;

    let nomeCliente = rawName;
    let rfid = '';
    const rfidMatch = rawName.match(/^(.+?)\s*\(([0-9a-f]{6,30})\)\s*$/i);
    if (rfidMatch) {
      nomeCliente = rfidMatch[1].trim();
      rfid = normalizarRFID(rfidMatch[2]);
    }

    const tipoOperacao = /^Recarga Livre$/i.test(nomeCliente)
      ? 'recarga_livre'
      : (rfid ? 'pos_pago' : 'avulso_app');

    // Remove data, duração, SoC e ano para sobrar os valores monetários/energia na ordem correta.
    let numStr = rowA.full;
    numStr = numStr.replace(/\d{2}\/\d{2}\/\d{4}/g, ' ');
    numStr = numStr.replace(/\d{1,2}h\s*\d{1,2}min(?:\s*\d{1,2}s)?/gi, ' ');
    numStr = numStr.replace(/\b\d{1,3}\s*-\s*\d{1,3}\b/g, ' ');
    numStr = numStr.replace(/\b20\d{2}\b/g, ' ');

    const nums = [];
    const numRe = /-?\d{1,4}[,.]\d{2}/g;
    let nm;
    while ((nm = numRe.exec(numStr)) !== null) nums.push(toNum(nm[0]));
    if (nums.length < 4) continue;

    const kwh = nums[0];
    const custo = nums[1];
    const cobranca = nums[2];
    const saldo = nums[3];
    const socMatch = rowA.full.match(/(\d{1,3})\s*-\s*(\d{1,3})/);
    const soc = socMatch ? `${socMatch[1]} - ${socMatch[2]}%` : '-';

    novas.push({
      id: 'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      rfid,
      nomeCliente,
      tipoOperacao,
      data: dateMatch[1] + ' ' + timeMatch[1],
      local: 'Pública ' + station,
      equipamento: station,
      duracao: durMatch[1].replace(/\s+/g, ' ').trim(),
      soc,
      kwh,
      tarifa: kwh > 0 ? parseFloat((custo / kwh).toFixed(4)) : 0,
      custo,
      cobranca,
      saldo,
      total: cobranca,
      fonte: filename,
      periodo
    });
  }

  // Parser de reforço por texto corrido: garante capturar todos os registros do relatório.
  // O parser por posição X/Y pode perder linhas quando o PDF muda espaçamento, página ou equipamento.
  const totalizadorMatch = plainText.match(/Totalizador das recargas:\s*(\d+)\s*Recargas/i);
  const totalEsperado = totalizadorMatch ? parseInt(totalizadorMatch[1], 10) : 0;
  const novasTexto = parseWemobPlainText(plainText, filename, periodo);
  if (novasTexto.length > novas.length || (totalEsperado && novas.length < totalEsperado && novasTexto.length >= novas.length)) {
    novas.length = 0;
    novas.push(...novasTexto);
  }

  document.getElementById('parse-progress').style.width = '100%';

  if (novas.length > 0) {
    classificarRecargasPorCliente(novas);
    if (!validarRFIDsAntesDeImportar(novas, filename, periodo)) return;

    const novasUnicas = [];
    const duplicadas = [];
    const uidsVistosNesteArquivo = new Set();
    novas.forEach(r => {
      prepararRecarga(r);
      const uid = r.uid || gerarRecargaUID(r);
      if (uidsVistosNesteArquivo.has(uid) || recargaJaExiste(r)) duplicadas.push(r);
      else { uidsVistosNesteArquivo.add(uid); novasUnicas.push(r); }
    });

    detectarDivergenciasTupi(novas);
    if (novasUnicas.length) {
      recargas = [...recargas, ...novasUnicas];
      classificarRecargasPorCliente(recargas);
      saveState();
      // Faturas não são geradas automaticamente — use Recargas Pendentes
    }

    document.getElementById('parse-badge').textContent = `${novasUnicas.length} novas / ${duplicadas.length} duplicadas`;
    document.getElementById('parse-badge').className = novasUnicas.length ? 'badge badge-green' : 'badge badge-yellow';
    renderParseResult(novasUnicas.length ? novasUnicas : novas, periodo);
    checkUnknownRFIDs(novasUnicas);
    renderRelatorios?.();
    toast(`${novasUnicas.length} recargas novas importadas. ${duplicadas.length} duplicada(s) ignorada(s).`, novasUnicas.length ? 'success' : 'error');
  } else {
    document.getElementById('parse-badge').textContent = 'Sem dados';
    document.getElementById('parse-badge').className = 'badge badge-red';
    document.getElementById('parse-content').innerHTML = `
      <div style="color:var(--red);font-size:13px;margin-bottom:8px">
        ⚠️ Não foi possível extrair recargas do PDF.<br>
        O PDF pode estar escaneado (imagem) ou em formato diferente.
      </div>
      <div style="background:var(--surface2);border-radius:8px;padding:12px;font-size:11px;font-family:'DM Mono',monospace;color:var(--text2);margin-bottom:12px;word-break:break-all;max-height:150px;overflow:auto">
        ${plainText.slice(0, 800)}
      </div>
      <button class="btn btn-secondary" onclick="loadSamplePDF()">📝 Carregar dados de exemplo</button>
    `;
  }
}

// Fallback: pure regex on concatenated text
function parseWemobFallback(text, clientBlocks, filename, novas, periodo) {
  // Pattern: date  time  duration  kwh  soc  custo  cobranca  saldo
  const rowRe = /(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2})\s+(\d{1,2}h\s*\d{1,2}min(?:\s*\d{1,2}s)?)\s+([\d,]+)\s+(\d{1,3})\s*-\s*(\d{1,3})\s+([\d,]+)\s+([\d,]+)\s+([\d,]+)/g;
  let m;
  while ((m = rowRe.exec(text)) !== null) {
    const dataHora = m[1] + ' ' + m[2];
    const duracao  = m[3].trim();
    const kwh      = parseFloat(m[4].replace(',','.'));
    const soc      = m[5] + ' - ' + m[6] + '%';
    const custo    = parseFloat(m[7].replace(',','.'));
    const cobranca = parseFloat(m[8].replace(',','.'));
    const saldo    = parseFloat(m[9].replace(',','.'));

    const pos = m.index;
    const nearby = text.slice(Math.max(0, pos - 400), pos + 50);
    let rfid = 'desconhecido', nomeCliente = 'Desconhecido', local = 'Eletroposto';

    // Find client: look for Nome (rfid) pattern near this match
    const nearClientMatch = nearby.match(/([A-Za-zÀ-ú\s]{3,}?)\s*\(([0-9a-f]{6,10})\)/i);
    if (nearClientMatch) {
      const nn = nearClientMatch[1].trim();
      if (!/^(P[uú]blica|Privada|Lefel)/i.test(nn) && nn.length >= 3) {
        rfid = nearClientMatch[2].toLowerCase();
        nomeCliente = nn;
      }
    }
    if (rfid === 'desconhecido') {
      clientBlocks.forEach(cb => {
        if (nearby.toLowerCase().includes(cb.rfid)) { rfid = cb.rfid; nomeCliente = cb.nome; }
      });
    }

    const localMatch = nearby.match(/Lefel[\w\s]*?\d+\s*kW[\w]*/i);
    if (localMatch) local = localMatch[0].trim();

    novas.push({
      id: 'rec_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
      rfid, nomeCliente, tipoOperacao: rfid && rfid !== 'desconhecido' ? 'pos_pago' : (nomeCliente === 'Recarga Livre' ? 'recarga_livre' : 'avulso_app'), data: dataHora, local, duracao, soc, kwh,
      tarifa: kwh > 0 ? parseFloat((custo/kwh).toFixed(4)) : 0,
      custo, cobranca, saldo, total: cobranca, fonte: filename, periodo: periodo||''
    });
  }
}


function validarRFIDsAntesDeImportar(novas, filename, periodo) {
  const pendentes = [...new Map(
    novas
      .filter(r => r.tipoOperacao === 'pos_pago' && r.rfid && !clientePorRFID(r.rfid))
      .map(r => [normalizarRFID(r.rfid), r])
  ).values()];

  if (!pendentes.length) return true;

  document.getElementById('parse-badge').textContent = 'Cadastro pendente';
  document.getElementById('parse-badge').className = 'badge badge-red';
  document.getElementById('parse-content').innerHTML = `
    <div style="background:var(--red-dim);border:1px solid rgba(239,68,68,0.35);border-radius:12px;padding:18px;margin-bottom:16px">
      <div style="font-size:15px;font-weight:800;color:var(--red);margin-bottom:8px">Importação bloqueada</div>
      <div style="font-size:13px;color:var(--text2);line-height:1.6">
        Este relatório possui cliente(s) pós-pago com RFID ainda não cadastrado(s).<br>
        Para evitar cobrança errada, nenhuma recarga deste relatório foi importada. Cadastre os clientes abaixo e importe o PDF novamente.
      </div>
    </div>
    ${pendentes.map(r => `
      <div style="background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-size:13px;font-weight:700">${r.nomeCliente}</div>
          <div style="font-size:11px;color:var(--accent);font-family:'DM Mono',monospace">${r.rfid}</div>
          <div style="font-size:11px;color:var(--text2);margin-top:3px">${r.data || ''} · R$ ${(r.cobranca ?? r.total ?? 0).toFixed(2).replace('.', ',')}</div>
        </div>
        <button class="btn btn-primary btn-sm" onclick="openModalClienteFromRFID('${r.rfid}','${String(r.nomeCliente || '').replace(/'/g, "\\'")}')">Cadastrar cliente</button>
      </div>
    `).join('')}
  `;
  setTimeout(() => openModalClienteFromRFID(pendentes[0].rfid, pendentes[0].nomeCliente), 250);
  return false;
}

function checkUnknownRFIDs(novas) {
  const rfids = [...new Set(novas.filter(r => r.tipoOperacao === 'pos_pago' && r.rfid).map(r => normalizarRFID(r.rfid)))];
  const desconhecidos = rfids.filter(r => !clientePorRFID(r));
  if (!desconhecidos.length) return;

  // Show alert in parse content
  const existingContent = document.getElementById('parse-content').innerHTML;
  const alertHtml = desconhecidos.map(rfid => {
    const rec = novas.find(r => r.rfid === rfid);
    return `
      <div style="background:var(--yellow-dim);border:1px solid rgba(245,158,11,0.3);border-radius:8px;padding:12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-size:12px;color:var(--yellow);font-weight:600">⚠️ RFID sem cliente vinculado</div>
          <div style="font-size:13px;font-weight:600;margin-top:2px">${rec?.nomeCliente || rfid}</div>
          <div style="font-size:11px;color:var(--text2);font-family:'DM Mono',monospace">${rfid}</div>
        </div>
        <button class="btn btn-secondary btn-sm" onclick="openModalClienteFromRFID('${rfid}','${rec?.nomeCliente||''}')">+ Cadastrar</button>
      </div>
    `;
  }).join('');

  document.getElementById('parse-content').innerHTML = alertHtml + existingContent;
}

function openModalClienteFromRFID(rfid, nome) {
  openModalCliente();
  setTimeout(() => {
    document.getElementById('c-rfid').value = rfid;
    const tipoEl = document.getElementById('c-tipo');
    if (tipoEl) tipoEl.value = 'pos';
    // Only pre-fill name if it looks like a real name (letters, spaces, accents)
    if (nome && /^[A-Za-zÀ-ú\s]{3,}$/.test(nome.trim())) {
      document.getElementById('c-nome').value = nome.trim();
    }
  }, 50);
}

