let editingEstacaoId = null;

// Retorna o nome canônico de uma estação pelo ID Tupi ou nome (pesquisa no cadastro)
function getEstacaoCadastrada(idTupi, nomeEstacao) {
  if (idTupi) {
    const e = estacoes.find(x => x.idTupi === String(idTupi));
    if (e) return e;
  }
  if (nomeEstacao) {
    const e = estacoes.find(x => x.nome === nomeEstacao);
    if (e) return e;
  }
  return null;
}

// ─── Taxa Tupi por estação (multi-CNPJ) ──────────────────────────────────────
// Cada estação pertence a um cadastro (CNPJ) na Tupi, com taxa própria
// (ex.: CNPJ atual = 8%, CNPJ novo = 10%). A taxa é configurada no cadastro
// da estação e GRAVADA em cada recarga na importação (taxaTupiPct/taxaTupi),
// preservando o histórico se a taxa mudar no futuro.
const TAXA_TUPI_PADRAO_PCT = 8;

// Percentual da taxa Tupi vigente para uma estação (por id Tupi e/ou nome).
function getTaxaTupiPctEstacao(idTupi, nomeEstacao) {
  const est = getEstacaoCadastrada(idTupi ? String(idTupi) : '', nomeEstacao || '');
  const pct = Number(est?.taxaTupiPct);
  return Number.isFinite(pct) && pct > 0 ? pct : TAXA_TUPI_PADRAO_PCT;
}

// Percentual aplicável a uma recarga: o gravado nela > o da estação > padrão.
function getTaxaTupiPctRecarga(r) {
  const gravado = Number(r?.taxaTupiPct);
  if (Number.isFinite(gravado) && gravado > 0) return gravado;
  return getTaxaTupiPctEstacao(r?.idEstacao, normalizarEstacao(r || {}));
}

// Valor da taxa Tupi de uma recarga.
// Base = valor BRUTO da sessão na Tupi (valor cobrado + cupom de desconto),
// pois a Tupi calcula a taxa sobre o bruto, sem considerar cupons.
function taxaTupiDaRecarga(r) {
  if (!r) return 0;
  if (r.taxaTupi != null && Number.isFinite(Number(r.taxaTupi))) return Number(r.taxaTupi);
  const valor = Number(r.cobranca ?? r.total ?? r.custo ?? 0);
  const cupom = Number(r.valorCupom || 0);
  if (!(valor + cupom > 0)) return 0;
  return (valor + cupom) * (getTaxaTupiPctRecarga(r) / 100);
}

// Soma da taxa Tupi de uma lista de recargas (usada pelos relatórios).
function somaTaxaTupi(lista) {
  return (lista || []).reduce((s, r) => s + taxaTupiDaRecarga(r), 0);
}

// Rótulo do percentual para exibição: "8%", "10%" ou "8–10%" quando misto.
function labelTaxaTupi(lista) {
  const pcts = [...new Set((lista || []).map(r => getTaxaTupiPctRecarga(r)))].sort((a, b) => a - b);
  if (!pcts.length) return TAXA_TUPI_PADRAO_PCT + '%';
  if (pcts.length === 1) return pcts[0] + '%';
  return pcts[0] + '–' + pcts[pcts.length - 1] + '%';
}

// Parceiro vinculado à estação (via cadastro de estações, preferencial, ou via equipamentos do parceiro)
function getParceiroDeEstacao(idTupi, nomeEstacao) {
  const est = getEstacaoCadastrada(idTupi, nomeEstacao);
  if (est?.parceiroId) return parceiros.find(p => p.id === est.parceiroId) || null;
  // fallback: varrer equipamentos dos parceiros
  return parceiros.find(p =>
    (Array.isArray(p.equipamentos) && p.equipamentos.some(eq =>
      eq === nomeEstacao || (idTupi && eq === String(idTupi))
    ))
  ) || null;
}

// Buffer temporário de documentos enquanto o modal está aberto
let estacaoDocsBuffer = []; // [{ nome, tipo, tamanho, base64, adicionadoEm }]

function openModalEstacao(id = null) {
  editingEstacaoId = id;
  const e = id ? estacoes.find(x => x.id === id) : null;
  document.getElementById('modal-estacao-title').textContent = id ? 'Editar Estação' : 'Nova Estação';
  const set = (key, val) => { const el = document.getElementById('est-' + key); if (el) el.value = val ?? ''; };
  set('nome',            e?.nome || '');
  set('idTupi',          e?.idTupi || '');
  set('taxaTupiPct',     e?.taxaTupiPct ?? TAXA_TUPI_PADRAO_PCT);
  set('endereco',        e?.endereco || '');
  set('potencia',        e?.potencia || '');
  set('conector',        e?.conector || '');
  set('obs',             e?.obs || '');
  set('investimento',    e?.investimento || '');
  set('dataInauguracao', e?.dataInauguracao || '');
  // Popular select de parceiros
  const sel = document.getElementById('est-parceiroId');
  sel.innerHTML = '<option value="">— sem parceiro —</option>'
    + parceiros.map(p => `<option value="${p.id}" ${e?.parceiroId === p.id ? 'selected' : ''}>${escapeHtml(p.nome)}</option>`).join('');
  // Carregar documentos existentes no buffer
  estacaoDocsBuffer = e?.documentos ? JSON.parse(JSON.stringify(e.documentos)) : [];
  renderEstacaoDocsLista();
  document.getElementById('modal-estacao').classList.add('open');
}

function renderEstacaoDocsLista() {
  const lista = document.getElementById('est-docs-lista');
  if (!lista) return;
  if (!estacaoDocsBuffer.length) {
    lista.innerHTML = '';
    return;
  }
  lista.innerHTML = estacaoDocsBuffer.map((doc, idx) => {
    const icone = doc.tipo?.includes('pdf') ? '📄'
      : doc.tipo?.includes('image') ? '🖼️'
      : doc.tipo?.includes('word') || doc.tipo?.includes('doc') ? '📝'
      : doc.tipo?.includes('sheet') || doc.tipo?.includes('excel') || doc.tipo?.includes('xls') ? '📊'
      : '📎';
    const tamanhoKb = (doc.tamanho / 1024).toFixed(1);
    return `
      <div style="display:flex;align-items:center;gap:10px;padding:8px 12px;background:var(--surface2);border-radius:8px;border:1px solid var(--border)">
        <span style="font-size:18px;flex-shrink:0">${icone}</span>
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(doc.nome)}</div>
          <div style="font-size:11px;color:var(--text3)">${tamanhoKb} KB · ${new Date(doc.adicionadoEm).toLocaleDateString('pt-BR')}</div>
        </div>
        <button class="btn btn-secondary btn-sm" onclick="baixarDocEstacao(${idx})" title="Baixar">⬇️</button>
        <button class="btn btn-danger btn-sm" onclick="removerDocEstacao(${idx})" title="Remover">🗑️</button>
      </div>`;
  }).join('');
}

async function handleEstacaoDocSelect(input) {
  const files = Array.from(input.files || []);
  input.value = '';
  await adicionarDocsEstacao(files);
}

async function handleEstacaoDocDrop(event) {
  const files = Array.from(event.dataTransfer.files || []);
  await adicionarDocsEstacao(files);
}

async function adicionarDocsEstacao(files) {
  const MAX = 5 * 1024 * 1024; // 5 MB
  for (const file of files) {
    if (file.size > MAX) { toast(`"${file.name}" excede 5 MB e foi ignorado.`, 'error'); continue; }
    try {
      const base64 = await new Promise((res, rej) => {
        const reader = new FileReader();
        reader.onload  = () => res(reader.result);
        reader.onerror = () => rej(new Error('Erro ao ler arquivo'));
        reader.readAsDataURL(file);
      });
      // Verificar se já existe pelo nome
      if (estacaoDocsBuffer.find(d => d.nome === file.name)) {
        toast(`"${file.name}" já está na lista.`, 'error');
        continue;
      }
      estacaoDocsBuffer.push({
        nome:        file.name,
        tipo:        file.type,
        tamanho:     file.size,
        base64,
        adicionadoEm: new Date().toISOString()
      });
    } catch { toast(`Erro ao processar "${file.name}".`, 'error'); }
  }
  renderEstacaoDocsLista();
}

function removerDocEstacao(idx) {
  estacaoDocsBuffer.splice(idx, 1);
  renderEstacaoDocsLista();
}

function baixarDocEstacao(idx) {
  const doc = estacaoDocsBuffer[idx];
  if (!doc) return;
  const a = document.createElement('a');
  a.href = doc.base64;
  a.download = doc.nome;
  a.click();
}

function salvarEstacao() {
  const get = key => document.getElementById('est-' + key)?.value?.trim() || '';
  if (!get('nome')) { toast('Informe o nome da estação.', 'error'); return; }
  const obj = {
    id:               editingEstacaoId || 'est_' + Date.now(),
    nome:             get('nome'),
    idTupi:           normalizarIdTupi(get('idTupi')),
    taxaTupiPct:      Number(get('taxaTupiPct')) > 0 ? Number(get('taxaTupiPct')) : TAXA_TUPI_PADRAO_PCT,
    parceiroId:       get('parceiroId') || null,
    endereco:         get('endereco'),
    potencia:         get('potencia'),
    conector:         get('conector'),
    obs:              get('obs'),
    investimento:     Number(get('investimento') || 0),
    dataInauguracao:  get('dataInauguracao') || '',
    documentos:       [...estacaoDocsBuffer],
    criadoEm:         editingEstacaoId ? estacoes.find(x=>x.id===editingEstacaoId)?.criadoEm : new Date().toISOString(),
    atualizadoEm:     new Date().toISOString()
  };

  // Atualizar ESTACAO_ID_MAP em memória com o nome canônico desta estação
  if (obj.idTupi) {
    ESTACAO_ID_MAP[obj.idTupi] = obj.nome;
    // Também registrar alias para normalização de recargas antigas (PDF)
    const nLow = obj.nome.toLowerCase().replace(/\s+/g, ' ');
    if (!ESTACAO_ALIASES[nLow]) ESTACAO_ALIASES[nLow] = obj.nome;
  }

  if (editingEstacaoId) {
    const estAntiga = estacoes.find(x => x.id === editingEstacaoId);
    // Se parceiroId mudou, remover do parceiro antigo
    if (estAntiga?.parceiroId && estAntiga.parceiroId !== obj.parceiroId) {
      const parceiroAntigo = parceiros.find(p => p.id === estAntiga.parceiroId);
      if (parceiroAntigo) {
        parceiroAntigo.equipamentos = (parceiroAntigo.equipamentos || []).filter(e => e !== estAntiga.nome && e !== obj.nome);
      }
    }
    const idx = estacoes.findIndex(x => x.id === editingEstacaoId);
    estacoes[idx] = obj;
    toast('Estação atualizada!', 'success');
  } else {
    estacoes.push(obj);
    toast('Estação cadastrada!', 'success');
  }
  // Sincronizar equipamentos no parceiro vinculado
  if (obj.parceiroId) {
    const nomeCanonEst = (obj.idTupi && ESTACAO_ID_MAP[obj.idTupi]) || obj.nome;
    const parceiroVinc = parceiros.find(p => p.id === obj.parceiroId);
    if (parceiroVinc && !parceiroVinc.equipamentos?.includes(nomeCanonEst)) {
      parceiroVinc.equipamentos = [...(parceiroVinc.equipamentos || []), nomeCanonEst];
    }
  }
  estacaoDocsBuffer = [];
  saveState();
  closeModal('modal-estacao');
  renderEstacoes();
}

function deletarEstacao(id) {
  if (!confirm('Excluir esta estação?')) return;
  estacoes = estacoes.filter(e => e.id !== id);
  saveState();
  renderEstacoes();
  toast('Estação removida.', 'success');
}

// ─── Limpeza de estações duplicadas ─────────────────────────────────────────
// Agrupa por ID Tupi (e por nome normalizado para as sem ID), mantém o melhor
// cadastro de cada grupo (prioriza o completado manualmente), mescla campos
// úteis das cópias e remove as duplicatas. Atualiza os vínculos dos parceiros.
function corrigirEstacoesDuplicadas() {
  const normNome = v => String(v || '').toLowerCase().replace(/^p[uú]blica\s+/i, '').replace(/\s+/g, ' ').trim();
  const grupos = new Map(); // chave: 'id:<idTupi>' ou 'nome:<nome-normalizado>'
  estacoes.forEach(e => {
    const id = normalizarIdTupi(e.idTupi);
    const chave = id ? 'id:' + id : 'nome:' + normNome(e.nome);
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(e);
  });

  // 2ª passada: estações SEM ID cujo nome bate com um grupo COM ID → juntam-se a ele
  for (const [chave, lista] of [...grupos.entries()]) {
    if (!chave.startsWith('nome:')) continue;
    const nomeGrupo = chave.slice(5);
    const alvo = [...grupos.entries()].find(([k, l]) =>
      k.startsWith('id:') && l.some(e => normNome(e.nome) === nomeGrupo)
    );
    if (alvo) { alvo[1].push(...lista); grupos.delete(chave); }
  }

  let removidas = 0, mescladas = 0;
  const renomeios = []; // [nomeAntigo, nomeFinal] p/ atualizar parceiros
  for (const lista of grupos.values()) {
    if (lista.length < 2) continue;
    // Pontuação: cadastro manual completo vence pendente automático
    const score = e =>
      (e.pendenteCadastro ? 0 : 100) +
      (e.parceiroId ? 20 : 0) +
      (normalizarIdTupi(e.idTupi) ? 10 : 0) +
      (e.endereco ? 3 : 0) + (e.potencia ? 2 : 0) +
      ((e.documentos || []).length ? 2 : 0) + (Number(e.investimento) > 0 ? 2 : 0);
    lista.sort((a, b) => score(b) - score(a));
    const principal = lista[0];
    for (const dup of lista.slice(1)) {
      // Mesclar o que o principal não tiver
      if (!normalizarIdTupi(principal.idTupi) && normalizarIdTupi(dup.idTupi)) principal.idTupi = normalizarIdTupi(dup.idTupi);
      if (!principal.parceiroId && dup.parceiroId) principal.parceiroId = dup.parceiroId;
      ['endereco', 'potencia', 'conector', 'dataInauguracao'].forEach(c => {
        if (!principal[c] && dup[c]) principal[c] = dup[c];
      });
      if (!Number(principal.investimento) && Number(dup.investimento)) principal.investimento = dup.investimento;
      if ((dup.documentos || []).length) principal.documentos = [...(principal.documentos || []), ...dup.documentos];
      if (Number(dup.taxaTupiPct) > 0 && !(Number(principal.taxaTupiPct) > 0)) principal.taxaTupiPct = dup.taxaTupiPct;
      if (String(dup.nome || '') !== String(principal.nome || '')) renomeios.push([dup.nome, principal.nome]);
      estacoes = estacoes.filter(e => e.id !== dup.id);
      removidas++;
    }
    principal.atualizadoEm = new Date().toISOString();
    if (normalizarIdTupi(principal.idTupi)) ESTACAO_ID_MAP[normalizarIdTupi(principal.idTupi)] = principal.nome;
    mescladas++;
  }

  // Atualizar vínculos de equipamentos nos parceiros (nome antigo → nome mantido)
  renomeios.forEach(([antigo, final]) => {
    parceiros.forEach(pr => {
      if (!Array.isArray(pr.equipamentos)) return;
      pr.equipamentos = [...new Set(pr.equipamentos.map(eq => eq === antigo ? final : eq))];
    });
  });

  if (removidas > 0) {
    saveState();
    renderEstacoes();
    toast(`${removidas} estação(ões) duplicada(s) removida(s) e mesclada(s). Os cadastros manuais foram preservados.`, 'success');
  } else {
    toast('Nenhuma duplicata encontrada — cadastros já estão íntegros.', 'success');
  }
}

function renderEstacoes() {
  const wrap = document.getElementById('estacoes-content');
  const resumoEl = document.getElementById('estacoes-resumo');
  if (!wrap) return;

  // Mês selecionado (ou atual)
  const mesInput = document.getElementById('estacoes-mes');
  // Ler APÓS o evento — garantir que o valor já foi atualizado
  const mesVal = (mesInput?.value || '').trim() || new Date().toISOString().slice(0,7);
  if (mesInput && !mesInput.value) mesInput.value = mesVal;

  // Estações: combinar cadastradas + as que só aparecem nas recargas (sem cadastro ainda)
  // Deduplicar por nome canônico (case-insensitive) e por idTupi
  // Nunca mostrar 'Não informado' na lista de estações
  const nomesNasRecargas = [...new Set(recargas.map(r => normalizarEstacao(r)).filter(n => n && n !== 'Não informado'))];

  // Conjunto de nomes e IDs já cobertos pelas estações cadastradas
  const nomesCadastrados = new Set(estacoes.map(e => e.nome.toLowerCase().replace(/\s+/g, ' ')));
  const idsCadastrados   = new Set(estacoes.map(e => e.idTupi).filter(Boolean));

  const estacoesParaMostrar = [
    ...estacoes,
    ...nomesNasRecargas
      .filter(nome => {
        const nLow = nome.toLowerCase().replace(/\s+/g, ' ');
        if (nomesCadastrados.has(nLow)) return false;
        // Verificar também pelo nome canônico (alias) para evitar duplicatas como "lefel 40kw" vs "Lefel 40kW DC"
        const canonLow = (ESTACAO_ALIASES[nLow] || nome).toLowerCase().replace(/\s+/g, ' ');
        if (canonLow !== nLow && nomesCadastrados.has(canonLow)) return false;
        // Verificar se o ID Tupi deste nome já está cadastrado
        const idTupi = Object.entries(ESTACAO_ID_MAP).find(([,v]) => v === nome || v === ESTACAO_ALIASES[nLow])?.[0] || '';
        if (idTupi && idsCadastrados.has(idTupi)) return false;
        return true;
      })
      .map(nome => ({
        id: null,
        nome,
        idTupi: Object.entries(ESTACAO_ID_MAP).find(([,v]) => v === nome)?.[0] || '',
        _semCadastro: true
      }))
  ];

  // Resumo geral
  const recargasMesResumo = recargas.filter(r => recargaPassaMes(r, mesVal) && !recargaOculta(r));
  const totalKwh  = recargasMesResumo.reduce((s,r) => s+(Number(r.kwh)||0), 0);
  const totalRecs = recargasMesResumo.length;
  const totalFaturado = recargasMesResumo.reduce((s,r) => s + Number(r.cobranca ?? r.total ?? r.valorTotal ?? r.custo ?? 0), 0);
  if (resumoEl) {
    resumoEl.innerHTML = `
      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px">
        <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:3px">ESTAÇÕES ATIVAS</div>
          <div style="font-size:22px;font-weight:800;color:var(--accent)">${estacoesParaMostrar.length}</div>
        </div>
        <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:3px">RECARGAS NO MÊS</div>
          <div style="font-size:22px;font-weight:800;color:var(--blue)">${totalRecs}</div>
        </div>
        <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:3px">kWh CONSUMIDOS</div>
          <div style="font-size:22px;font-weight:800;color:var(--yellow)">${totalKwh.toFixed(2)}</div>
        </div>
        <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:3px">VALOR TOTAL FATURADO</div>
          <div style="font-size:22px;font-weight:800;color:var(--green)">${moneyBR(totalFaturado)}</div>
        </div>
      </div>`;
  }

  if (!estacoesParaMostrar.length) {
    wrap.innerHTML = `<div class="empty-state"><div class="empty-icon">🔌</div><div class="empty-title">Nenhuma estação cadastrada</div><div class="empty-sub">Cadastre estações ou importe um CSV da Tupi para que apareçam automaticamente.</div></div>`;
    return;
  }

  wrap.innerHTML = estacoesParaMostrar.map(e => {
    // Comparar pelo nome canônico: cobre casos onde e.nome tem grafia antiga no banco
    const _nomeCanonEst = ESTACAO_ALIASES[e.nome.toLowerCase().replace(/\s+/g,' ')] || e.nome;
    const recsMes  = recargas.filter(r => recargaPassaMes(r, mesVal) && (normalizarEstacao(r) === _nomeCanonEst || normalizarEstacao(r) === e.nome));
    const kwhMes   = recsMes.reduce((s,r) => s+(r.kwh||0), 0);
    const valorMes = recsMes.reduce((s,r) => s+(r.cobranca||0), 0);
    const parceiro = e.parceiroId ? parceiros.find(p => p.id === e.parceiroId) : null;

    return `
      <div class="card" style="margin-bottom:14px${e._semCadastro ? ';border-color:var(--border2)' : ''}">
        <div class="card-header">
          <div style="display:flex;gap:12px;align-items:center">
            <div style="font-size:28px">🔌</div>
            <div>
              <div style="font-size:15px;font-weight:700">${escapeHtml(e.nome)}</div>
              <div style="font-size:11px;color:var(--text2);margin-top:2px">
                ${e.idTupi ? `ID Tupi: <span class="mono">${e.idTupi}</span>` : ''}
                ${e.idTupi && (e.endereco || parceiro) ? ' · ' : ''}
                ${e.endereco ? escapeHtml(e.endereco) : ''}
              </div>
              <div style="font-size:11px;color:var(--text3);margin-top:2px">
                ${parceiro ? `Parceiro: <strong style="color:var(--text)">${escapeHtml(parceiro.nome)}</strong>` : '<span style="color:var(--yellow)">⚠️ Sem parceiro vinculado</span>'}
                ${e.potencia ? ` · ${e.potencia} kW` : ''}
                ${e.conector ? ` · ${escapeHtml(e.conector)}` : ''}
              </div>
              ${e._semCadastro ? `<div style="font-size:10px;color:var(--text3);margin-top:3px;font-style:italic">Detectada nas recargas — clique em Cadastrar para adicionar dados</div>` : ''}
            </div>
          </div>
          <div style="display:flex;gap:8px;align-items:center;flex-shrink:0">
            ${e._semCadastro
              ? `<button class="btn btn-secondary btn-sm" onclick="openModalEstacaoPreenchida('${escapeHtml(e.nome)}','${e.idTupi||''}')">＋ Cadastrar</button>`
              : `<button class="btn btn-secondary btn-sm" onclick="openModalEstacao('${e.id}')">✏️ Editar</button>
                 <button class="btn btn-danger btn-sm" onclick="deletarEstacao('${e.id}')">🗑️</button>`
            }
          </div>
        </div>
        <!-- Mini resumo do período -->
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px">
          <div style="background:var(--surface2);border-radius:8px;padding:10px 14px;text-align:center">
            <div style="font-size:10px;color:var(--text3)">RECARGAS</div>
            <div style="font-size:18px;font-weight:700;color:var(--accent)">${recsMes.length}</div>
          </div>
          <div style="background:var(--surface2);border-radius:8px;padding:10px 14px;text-align:center">
            <div style="font-size:10px;color:var(--text3)">kWh</div>
            <div style="font-size:18px;font-weight:700;color:var(--blue)">${kwhMes.toFixed(2)}</div>
          </div>
          <div style="background:var(--surface2);border-radius:8px;padding:10px 14px;text-align:center">
            <div style="font-size:10px;color:var(--text3)">FATURAMENTO</div>
            <div style="font-size:18px;font-weight:700;color:var(--yellow)">${moneyBR(valorMes)}</div>
          </div>
        </div>
        ${!e._semCadastro && e.documentos && e.documentos.length ? `
        <!-- Documentos anexados -->
        <div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--border)">
          <div style="font-size:12px;color:var(--text2);margin-bottom:8px;font-weight:600">
            📎 ${e.documentos.length} documento(s) anexado(s)
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:8px">
            ${e.documentos.map((doc, idx) => {
              const icone = doc.tipo?.includes('pdf') ? '📄'
                : doc.tipo?.includes('image') ? '🖼️'
                : doc.tipo?.includes('word') || doc.tipo?.includes('doc') ? '📝'
                : doc.tipo?.includes('sheet') || doc.tipo?.includes('excel') || doc.tipo?.includes('xls') ? '📊'
                : '📎';
              return `<button class="btn btn-secondary btn-sm" style="font-size:11px" 
                onclick="baixarDocEstacaoById('${e.id}',${idx})" title="Baixar ${escapeHtml(doc.nome)}">
                ${icone} ${escapeHtml(doc.nome.length > 20 ? doc.nome.slice(0,18)+'…' : doc.nome)}
              </button>`;
            }).join('')}
          </div>
        </div>` : ''}
      </div>`;
  }).join('');
}

// Abre modal de estação já pré-preenchida com nome e ID da Tupi (para estações detectadas nas recargas)
function openModalEstacaoPreenchida(nome, idTupi) {
  openModalEstacao(null);
  setTimeout(() => {
    document.getElementById('est-nome').value = nome;
    document.getElementById('est-idTupi').value = idTupi || '';
  }, 30);
}

// Download de documento diretamente da listagem (sem abrir modal)
function baixarDocEstacaoById(estacaoId, docIdx) {
  const est = estacoes.find(e => e.id === estacaoId);
  const doc = est?.documentos?.[docIdx];
  if (!doc) return;
  const a = document.createElement('a');
  a.href = doc.base64;
  a.download = doc.nome;
  a.click();
}

// ═══════════════════════════════════════
//  PAYBACK
// ═══════════════════════════════════════

function formatTempoOperacao(dataInicio) {
  if (!dataInicio) return '—';
  const inicio = dataInicio instanceof Date ? dataInicio : new Date(dataInicio);
  if (Number.isNaN(inicio.getTime())) return '—';
  const hoje = new Date();
  let meses = (hoje.getFullYear() - inicio.getFullYear()) * 12 + (hoje.getMonth() - inicio.getMonth());
  if (hoje.getDate() < inicio.getDate()) meses -= 1;
  meses = Math.max(0, meses);
  const anos = Math.floor(meses / 12);
  const resto = meses % 12;
  const partes = [];
  if (anos) partes.push(`${anos} ${anos === 1 ? 'ano' : 'anos'}`);
  if (resto) partes.push(`${resto} ${resto === 1 ? 'mês' : 'meses'}`);
  if (!partes.length) {
    const dias = Math.max(0, Math.floor((hoje - inicio) / 86400000));
    return `${dias} ${dias === 1 ? 'dia' : 'dias'}`;
  }
  return partes.join(' e ');
}

function primeiraRecargaEstacao(estacao) {
  const nomeEst = normalizarTextoChave(estacao.nome || '');
  const idTupi = String(estacao.idTupi || '').trim();
  const datas = recargas
    .filter(r => !recargaOculta(r) && r.tipoOperacao !== 'sessao_cancelada')
    .filter(r => {
      const mesmoId = idTupi && String(r.idEstacao || '') === idTupi;
      const mesmoNome = normalizarTextoChave(getEquipamentoRecarga(r)) === nomeEst;
      return mesmoId || mesmoNome;
    })
    .map(r => dataParaDate(r))
    .filter(Boolean)
    .sort((a, b) => a - b);
  return datas[0] || null;
}

function renderPayback() {
  const wrap = document.getElementById('payback-content');
  if (!wrap) return;

  // Apenas estações com investimento cadastrado
  const estacoesComInv = estacoes.filter(e => Number(e.investimento || 0) > 0);

  if (!estacoesComInv.length) {
    wrap.innerHTML = `
      <div class="card">
        <div class="empty-state" style="padding:48px">
          <div class="empty-icon">📈</div>
          <div class="empty-title">Nenhuma estação com investimento cadastrado</div>
          <div class="empty-sub">Cadastre o valor de investimento de cada estação no módulo <strong>Estações</strong> para visualizar o payback.</div>
          <button class="btn btn-primary" style="margin-top:20px" onclick="goTo('estacoes')">🔌 Ir para Estações</button>
        </div>
      </div>`;
    return;
  }

  // Para cada estação, calcular lucro líquido por mês usando a mesma lógica do módulo Parceiros
  // (espelha calcularRelatorioParceiro → lucroEVParking).
  //
  // IMPORTANTE — custos do PARCEIRO (mensalidade e compromisso mínimo da comissão)
  // são calculados no nível do parceiro/mês (como no fechamento real) e RATEADOS
  // entre as estações dele pela participação na receita. Antes, eram descontados
  // por inteiro em cada estação, dobrando o custo em parceiros multi-estação.

  // Recargas e dados mensais de uma estação — vínculo pelo ID Tupi (definitivo),
  // com fallback por nome para recargas antigas sem idEstacao.
  const _cacheDadosMes = new Map();
  function dadosMesEstacao(estacao) {
    if (_cacheDadosMes.has(estacao.id)) return _cacheDadosMes.get(estacao.id);
    const idEst = String(estacao.idTupi || '').replace(/\D/g, '');
    const recsEstacao = recargas.filter(r => {
      const valor = Number(r.cobranca ?? r.total ?? r.custo ?? 0);
      if (!(valor > 0) || recargaOculta(r)) return false;
      const idRec = String(r.idEstacao || '').replace(/\D/g, '');
      if (idEst && idRec) return idRec === idEst;               // 1º: ID com ID
      return normalizarEstacao(r) === estacao.nome;             // 2º: nome canônico
    });
    const porMes = {};
    const parceiro = estacao.parceiroId ? parceiros.find(p => p.id === estacao.parceiroId) : null;
    const custoEnUnit = parceiro ? Number(parceiro.custoEnergia || 0) : 0;
    recsEstacao.forEach(r => {
      const key = recargaMesKey(r);
      if (!key) return;
      if (!porMes[key]) porMes[key] = { bruto: 0, kwh: 0, descontos: 0, taxaTupi: 0, recLiq: 0, custoEn: 0 };
      const m = porMes[key];
      m.bruto     += Number(r.cobranca ?? r.total ?? r.custo ?? 0);
      m.kwh       += Number(r.kwh || 0);
      m.descontos += descontoPosPagoDaRecarga(r);
      m.taxaTupi  += taxaTupiDaRecarga(r);
    });
    Object.values(porMes).forEach(m => {
      m.recLiq  = Math.max(0, m.bruto - m.descontos);
      m.custoEn = m.kwh * custoEnUnit;
    });
    _cacheDadosMes.set(estacao.id, porMes);
    return porMes;
  }

  // Comissão + mensalidade do parceiro por mês (nível parceiro, com piso mínimo),
  // somando TODAS as estações vinculadas a ele — igual ao fechamento.
  const _cacheParceiroMes = new Map();
  function custosParceiroMes(parceiro) {
    if (_cacheParceiroMes.has(parceiro.id)) return _cacheParceiroMes.get(parceiro.id);
    const estacoesDoParceiro = estacoes.filter(e => e.parceiroId === parceiro.id);
    const porMes = {}; // mes → { recLiq, custoEn }
    estacoesDoParceiro.forEach(e => {
      const dm = dadosMesEstacao(e);
      Object.entries(dm).forEach(([mes, m]) => {
        if (!porMes[mes]) porMes[mes] = { recLiq: 0, custoEn: 0 };
        porMes[mes].recLiq  += m.recLiq;
        porMes[mes].custoEn += m.custoEn;
      });
    });
    const mensalidade = Number(parceiro.mensalidade || 0);
    const taxaOpPct   = Number(parceiro.taxaOperacional || 0);
    const comissaoPct = Number(parceiro.comissao || 0);
    const minimo      = Number(parceiro.compromisoMinimo || 0);
    const resultado = {};
    Object.entries(porMes).forEach(([mes, t]) => {
      const taxaOp        = t.recLiq * (taxaOpPct / 100);
      const lucroBase     = t.recLiq - t.custoEn - taxaOp - mensalidade;
      const comissaoBruta = Math.max(0, lucroBase) * (comissaoPct / 100);
      const comissao      = minimo > 0 ? Math.max(comissaoBruta, minimo) : comissaoBruta;
      resultado[mes] = { recLiqTotal: t.recLiq, comissao, mensalidade };
    });
    _cacheParceiroMes.set(parceiro.id, resultado);
    return resultado;
  }

  function getLucroEstacaoPorMes(estacao) {
    const parceiro = estacao.parceiroId ? parceiros.find(p => p.id === estacao.parceiroId) : null;
    const porMes = dadosMesEstacao(estacao);
    const custosParc = parceiro ? custosParceiroMes(parceiro) : {};

    return Object.entries(porMes).sort(([a],[b]) => a.localeCompare(b)).map(([mesKey, m]) => {
      // Rateio dos custos do parceiro pela participação da estação na receita do mês
      const cp = custosParc[mesKey];
      const share = cp && cp.recLiqTotal > 0 ? (m.recLiq / cp.recLiqTotal) : 0;
      const custoParceiroRateado = cp ? share * (cp.comissao + cp.mensalidade) : 0;
      // Lucro EV Parking da estação = receita líq. − taxa Tupi − custo energia − rateio(comissão + mensalidade)
      // Meses negativos ABATEM o acumulado do payback (não são zerados).
      const lucroLiq = m.recLiq - m.taxaTupi - m.custoEn - custoParceiroRateado;
      return { mesKey, bruto: m.bruto, kwh: m.kwh, lucroLiq };
    });
  }

  // Formatar mês YYYY-MM → "Jan/2026"
  function fmtMes(key) {
    const [y, m] = key.split('-');
    const meses = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
    return `${meses[parseInt(m,10)-1]}/${y}`;
  }

  // Gerar SVG de gráfico de barras simples
  function gerarGraficoBarras(dadosMes, investimento) {
    if (!dadosMes.length) return '<div style="color:var(--text3);font-size:12px;padding:12px 0">Sem dados de recargas para esta estação.</div>';
    const maxVal = Math.max(...dadosMes.map(d => d.lucroLiq), 1);
    const W = 560, H = 140, padL = 8, padR = 8, padT = 10, padB = 30;
    const plotW = W - padL - padR;
    const plotH = H - padT - padB;
    const barW  = Math.min(40, (plotW / dadosMes.length) - 4);
    const gap   = (plotW - barW * dadosMes.length) / (dadosMes.length + 1);

    let acumulado = 0;
    const bars = dadosMes.map((d, i) => {
      acumulado += d.lucroLiq;
      const x   = padL + gap + i * (barW + gap);
      const h   = Math.max(2, (Math.max(0, d.lucroLiq) / maxVal) * plotH);
      const y   = padT + plotH - h;
      // Cor: vermelho até recuperar, verde depois
      const cor = acumulado >= investimento ? '#00e5a0' : '#3b82f6';
      const label = fmtMes(d.mesKey);
      return `
        <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="3" fill="${cor}" opacity="0.85"/>
        <text x="${x + barW/2}" y="${H - padB + 14}" text-anchor="middle" font-size="9" fill="#8fa3bc">${label}</text>
        <text x="${x + barW/2}" y="${y - 3}" text-anchor="middle" font-size="8" fill="${cor}">R$${(d.lucroLiq/1000).toFixed(1)}k</text>
      `;
    }).join('');

    // Linha de break-even proporcional
    const totalRec = dadosMes.reduce((s,d) => s + d.lucroLiq, 0);
    const pctRecup = Math.min(1, totalRec / investimento);

    return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;max-width:${W}px;height:${H}px;display:block">
      <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT+plotH}" stroke="#1e2d42" stroke-width="1"/>
      <line x1="${padL}" y1="${padT+plotH}" x2="${W-padR}" y2="${padT+plotH}" stroke="#1e2d42" stroke-width="1"/>
      ${bars}
    </svg>`;
  }

  // ── Calcular totais gerais para o box de payback consolidado ──
  const resumoGeral = estacoesComInv.map(estacao => {
    const inv = Number(estacao.investimento || 0);
    const dadosMes = getLucroEstacaoPorMes(estacao);
    const recup = dadosMes.reduce((s, d) => s + d.lucroLiq, 0);
    const ultimos3 = dadosMes.slice(-3);
    const media = ultimos3.length ? ultimos3.reduce((s, d) => s + d.lucroLiq, 0) / ultimos3.length : 0;
    return { inv, recup, media };
  });
  const totalInvGeral   = resumoGeral.reduce((s, r) => s + r.inv, 0);
  const totalRecupGeral = resumoGeral.reduce((s, r) => s + r.recup, 0);
  const totalMediaGeral = resumoGeral.reduce((s, r) => s + r.media, 0);
  const pctGeral        = totalInvGeral > 0 ? Math.min(100, (totalRecupGeral / totalInvGeral) * 100) : 0;
  const faltaGeral      = Math.max(0, totalInvGeral - totalRecupGeral);
  const atingidoGeral   = totalRecupGeral >= totalInvGeral;
  const mesesRestGeral  = (totalMediaGeral > 0 && !atingidoGeral) ? Math.ceil(faltaGeral / totalMediaGeral) : null;
  const corGeral        = atingidoGeral ? 'var(--accent)' : pctGeral > 60 ? 'var(--blue)' : pctGeral > 30 ? 'var(--yellow)' : 'var(--red)';

  const summaryBox = `
    <div class="card" style="margin-bottom:28px;border:2px solid var(--border2);background:linear-gradient(135deg,var(--surface) 0%,var(--surface2) 100%)">
      <div style="font-size:14px;font-weight:700;margin-bottom:16px;display:flex;align-items:center;gap:10px">
        📊 Consolidado Geral
        <span style="font-size:11px;font-weight:400;color:var(--text3)">${estacoesComInv.length} estação(ões) com investimento cadastrado</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px">
        <div style="background:var(--surface3);border-radius:10px;padding:14px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:4px">INVESTIMENTO TOTAL</div>
          <div style="font-size:18px;font-weight:800;color:var(--text)">${totalInvGeral.toLocaleString('pt-BR',{minimumFractionDigits:2})}</div>
        </div>
        <div style="background:var(--surface3);border-radius:10px;padding:14px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:4px">TOTAL RECUPERADO</div>
          <div style="font-size:18px;font-weight:800;color:var(--accent)">${totalRecupGeral.toLocaleString('pt-BR',{minimumFractionDigits:2})}</div>
        </div>
        <div style="background:var(--surface3);border-radius:10px;padding:14px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:4px">${atingidoGeral ? 'EXCEDENTE' : 'FALTA'}</div>
          <div style="font-size:18px;font-weight:800;color:${atingidoGeral ? 'var(--accent)' : 'var(--red)'}">
            ${atingidoGeral ? '+' : ''}${(atingidoGeral ? totalRecupGeral - totalInvGeral : faltaGeral).toLocaleString('pt-BR',{minimumFractionDigits:2})}
          </div>
        </div>
        <div style="background:var(--surface3);border-radius:10px;padding:14px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:4px">MÉDIA MENSAL (3M)</div>
          <div style="font-size:18px;font-weight:800;color:var(--blue)">${totalMediaGeral > 0 ? totalMediaGeral.toLocaleString('pt-BR',{minimumFractionDigits:2}) : '—'}</div>
        </div>
        <div style="background:var(--surface3);border-radius:10px;padding:14px 16px;text-align:center">
          <div style="font-size:10px;color:var(--text3);margin-bottom:4px">${atingidoGeral ? 'PAYBACK ATINGIDO ✅' : 'PREVISÃO PAYBACK'}</div>
          <div style="font-size:18px;font-weight:800;color:${atingidoGeral ? 'var(--accent)' : 'var(--text)'}">
            ${atingidoGeral ? '100%' : mesesRestGeral !== null ? `~${mesesRestGeral} ${mesesRestGeral === 1 ? 'mês' : 'meses'}` : '—'}
          </div>
        </div>
      </div>
      <div style="margin-bottom:6px;display:flex;justify-content:space-between">
        <span style="font-size:12px;color:var(--text2)">Progresso consolidado de recuperação</span>
        <span style="font-size:14px;font-weight:700;color:${corGeral}">${pctGeral.toFixed(1)}%</span>
      </div>
      <div style="height:12px;background:var(--surface3);border-radius:6px;overflow:hidden">
        <div style="height:100%;width:${pctGeral}%;background:${corGeral};border-radius:6px;transition:width 0.6s ease;min-width:${pctGeral>0?'4px':'0'}"></div>
      </div>
    </div>
  `;

  wrap.innerHTML = summaryBox + estacoesComInv.map(estacao => {
    const investimento  = Number(estacao.investimento || 0);
    const dadosMes      = getLucroEstacaoPorMes(estacao);
    const totalRecup    = dadosMes.reduce((s, d) => s + d.lucroLiq, 0);
    const pct           = investimento > 0 ? Math.min(100, (totalRecup / investimento) * 100) : 0;
    const falta         = Math.max(0, investimento - totalRecup);
    const parceiro      = estacao.parceiroId ? parceiros.find(p => p.id === estacao.parceiroId) : null;
    const atingido      = totalRecup >= investimento;

    // Estimar prazo restante com base na média dos últimos 3 meses
    const ultimos3 = dadosMes.slice(-3);
    const mediaLL  = ultimos3.length ? ultimos3.reduce((s,d) => s+d.lucroLiq, 0) / ultimos3.length : 0;
    const mesesRest = (mediaLL > 0 && !atingido) ? Math.ceil(falta / mediaLL) : null;

    // Data de início: obrigatoriamente do campo dataInauguracao (sem fallback)
    const dataInicio = estacao.dataInauguracao || '';
    const primeiraRecarga = primeiraRecargaEstacao(estacao);
    const dataInicioBase = primeiraRecarga || (dataInicio ? new Date(dataInicio + 'T00:00:00') : null);
    const dataInicioLabel = dataInicioBase
      ? dataInicioBase.toLocaleDateString('pt-BR')
      : '—';
    const tempoOperacaoLabel = formatTempoOperacao(dataInicioBase);

    const corPct = atingido ? 'var(--accent)' : pct > 60 ? 'var(--blue)' : pct > 30 ? 'var(--yellow)' : 'var(--red)';

    return `
      <div class="card" style="margin-bottom:24px">
        <!-- Cabeçalho -->
        <div class="card-header" style="margin-bottom:16px">
          <div>
            <div style="font-size:16px;font-weight:700">🔌 ${escapeHtml(estacao.nome)}</div>
            <div style="font-size:12px;color:var(--text2);margin-top:3px">
              ${estacao.endereco ? escapeHtml(estacao.endereco) + ' · ' : ''}
              Parceiro: ${parceiro ? escapeHtml(parceiro.nome) : '<span style="color:var(--text3)">não vinculado</span>'}
              · Primeira recarga: ${dataInicioLabel} · Tempo decorrido: <strong style="color:var(--accent)">${tempoOperacaoLabel}</strong>
            </div>
          </div>
          <button class="btn btn-secondary btn-sm" onclick="goTo('estacoes')">✏️ Editar estação</button>
        </div>

        <!-- KPIs principais -->
        <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:20px">
          <div style="background:var(--surface2);border-radius:10px;padding:14px 16px;text-align:center">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">INVESTIMENTO</div>
            <div style="font-size:18px;font-weight:800;color:var(--text)">R$ ${investimento.toLocaleString('pt-BR',{minimumFractionDigits:2})}</div>
          </div>
          <div style="background:var(--surface2);border-radius:10px;padding:14px 16px;text-align:center">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">TEMPO DECORRIDO</div>
            <div style="font-size:18px;font-weight:800;color:var(--accent)">${tempoOperacaoLabel}</div>
          </div>
          <div style="background:var(--surface2);border-radius:10px;padding:14px 16px;text-align:center">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">JÁ RECUPERADO</div>
            <div style="font-size:18px;font-weight:800;color:${corPct}">R$ ${totalRecup.toLocaleString('pt-BR',{minimumFractionDigits:2})}</div>
          </div>
          <div style="background:var(--surface2);border-radius:10px;padding:14px 16px;text-align:center">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">${atingido ? 'EXCEDENTE' : 'FALTA'}</div>
            <div style="font-size:18px;font-weight:800;color:${atingido ? 'var(--accent)' : 'var(--red)'}">
              ${atingido ? '+' : ''}R$ ${(atingido ? totalRecup - investimento : falta).toLocaleString('pt-BR',{minimumFractionDigits:2})}
            </div>
          </div>
          <div style="background:var(--surface2);border-radius:10px;padding:14px 16px;text-align:center">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">${atingido ? 'PAYBACK ATINGIDO ✅' : 'PREVISÃO PAYBACK'}</div>
            <div style="font-size:18px;font-weight:800;color:${atingido ? 'var(--accent)' : 'var(--text)'}">
              ${atingido ? '100%' : mesesRest !== null ? `~${mesesRest} ${mesesRest === 1 ? 'mês' : 'meses'}` : '—'}
            </div>
          </div>
        </div>

        <!-- Barra de progresso -->
        <div style="margin-bottom:20px">
          <div style="display:flex;justify-content:space-between;margin-bottom:6px">
            <span style="font-size:12px;color:var(--text2)">Progresso de recuperação</span>
            <span style="font-size:14px;font-weight:700;color:${corPct}">${pct.toFixed(1)}%</span>
          </div>
          <div style="height:14px;background:var(--surface3);border-radius:7px;overflow:hidden">
            <div style="height:100%;width:${pct}%;background:${corPct};border-radius:7px;transition:width 0.6s ease;min-width:${pct>0?'4px':'0'}"></div>
          </div>
          ${mediaLL > 0 && !atingido ? `
            <div style="font-size:11px;color:var(--text3);margin-top:6px">
              Média últimos 3 meses: R$ ${mediaLL.toLocaleString('pt-BR',{minimumFractionDigits:2})}/mês de lucro líquido
            </div>` : ''}
        </div>

        <!-- Gráfico de barras mensais -->
        <div>
          <div style="font-size:12px;color:var(--text2);margin-bottom:8px;font-weight:600">
            Lucro líquido mensal
            <span style="font-weight:400;margin-left:8px">
              <span style="color:var(--blue)">■</span> recuperando &nbsp;
              <span style="color:var(--accent)">■</span> payback atingido
            </span>
          </div>
          ${gerarGraficoBarras(dadosMes, investimento)}
          ${dadosMes.length === 0 ? '' : `
            <div style="font-size:11px;color:var(--text3);margin-top:6px">
              ${dadosMes.length} mês(es) de operação · Total: R$ ${totalRecup.toLocaleString('pt-BR',{minimumFractionDigits:2})} de lucro líquido acumulado
            </div>`}
        </div>
      </div>
    `;
  }).join('');
}

// ═══════════════════════════════════════
//  DASHBOARD
// ═══════════════════════════════════════
function parseDataDashboard(value) {
  if (!value) return null;
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  const str = String(value).trim();
  const br = str.match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);
  if (br) return new Date(Number(br[3]), Number(br[2]) - 1, Number(br[1]), Number(br[4] || 0), Number(br[5] || 0));
  const iso = new Date(str);
  return Number.isNaN(iso.getTime()) ? null : iso;
}

function inicioDoDia(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function fimDoDia(d) {
  const x = new Date(d);
  x.setHours(23, 59, 59, 999);
  return x;
}

// Tipos de período padronizados (usados no dashboard e reutilizáveis em
// outras telas via aplicarPresetPeriodo): current_month, last_month,
// two_months_ago, today, current_year, all, custom.
const PERIODO_TIPOS_VALIDOS = ['current_month', 'last_month', 'two_months_ago', 'today', 'current_year', 'all', 'custom'];

function labelMesAno(d) {
  const l = d.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
  return l.charAt(0).toUpperCase() + l.slice(1);
}

// Calcula {inicio, fim, label} para um tipo de período padronizado.
function calcularPeriodoPadrao(tipo, customStart, customEnd) {
  const hoje = new Date();
  let inicio = null, fim = null, label = 'Tudo';

  if (tipo === 'today') {
    inicio = inicioDoDia(hoje);
    fim = fimDoDia(hoje);
    label = 'Hoje (' + hoje.toLocaleDateString('pt-BR') + ')';
  } else if (tipo === 'last_month') {
    const base = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
    inicio = inicioDoDia(base);
    fim = fimDoDia(new Date(base.getFullYear(), base.getMonth() + 1, 0));
    label = labelMesAno(base);
  } else if (tipo === 'two_months_ago') {
    const base = new Date(hoje.getFullYear(), hoje.getMonth() - 2, 1);
    inicio = inicioDoDia(base);
    fim = fimDoDia(new Date(base.getFullYear(), base.getMonth() + 1, 0));
    label = labelMesAno(base);
  } else if (tipo === 'current_year') {
    inicio = inicioDoDia(new Date(hoje.getFullYear(), 0, 1));
    fim = fimDoDia(new Date(hoje.getFullYear(), 11, 31));
    label = String(hoje.getFullYear());
  } else if (tipo === 'custom') {
    inicio = customStart ? inicioDoDia(new Date(customStart + 'T00:00:00')) : null;
    fim = customEnd ? fimDoDia(new Date(customEnd + 'T23:59:59')) : null;
    const iniTxt = inicio ? inicio.toLocaleDateString('pt-BR') : 'início';
    const fimTxt = fim ? fim.toLocaleDateString('pt-BR') : 'hoje';
    label = `${iniTxt} até ${fimTxt}`;
  } else if (tipo === 'all') {
    label = 'Tudo';
  } else { // current_month (padrão)
    inicio = inicioDoDia(new Date(hoje.getFullYear(), hoje.getMonth(), 1));
    fim = fimDoDia(new Date(hoje.getFullYear(), hoje.getMonth() + 1, 0));
    label = labelMesAno(hoje);
  }
  return { inicio, fim, label, tipo: PERIODO_TIPOS_VALIDOS.includes(tipo) ? tipo : 'current_month' };
}

function getDashboardPeriodo() {
  // Normalizar valores antigos salvos (ex.: 'last_30' de versões anteriores)
  if (!PERIODO_TIPOS_VALIDOS.includes(dashboardPeriodoTipo)) dashboardPeriodoTipo = 'current_month';
  return calcularPeriodoPadrao(dashboardPeriodoTipo, dashboardPeriodoCustomStart, dashboardPeriodoCustomEnd);
}

// ── Período anterior equivalente (para os cards de comparação) ──────────────
// Retorna null quando não há comparação possível (tipo 'all').
function getDashboardPeriodoAnterior(periodo) {
  const tipo = periodo.tipo;
  const hoje = new Date();
  if (tipo === 'all') return null;

  if (tipo === 'current_month')  return calcularPeriodoPadrao('last_month');
  if (tipo === 'last_month')     return calcularPeriodoPadrao('two_months_ago');
  if (tipo === 'two_months_ago') {
    const base = new Date(hoje.getFullYear(), hoje.getMonth() - 3, 1);
    return { inicio: inicioDoDia(base), fim: fimDoDia(new Date(base.getFullYear(), base.getMonth() + 1, 0)), label: labelMesAno(base), tipo: 'custom' };
  }
  if (tipo === 'today') {
    const ontem = new Date(hoje.getFullYear(), hoje.getMonth(), hoje.getDate() - 1);
    return { inicio: inicioDoDia(ontem), fim: fimDoDia(ontem), label: 'Ontem (' + ontem.toLocaleDateString('pt-BR') + ')', tipo: 'custom' };
  }
  if (tipo === 'current_year') {
    const ano = hoje.getFullYear() - 1;
    return { inicio: inicioDoDia(new Date(ano, 0, 1)), fim: fimDoDia(new Date(ano, 11, 31)), label: String(ano), tipo: 'custom' };
  }
  // custom: mesma duração, imediatamente anterior
  if (periodo.inicio && periodo.fim) {
    const dur = periodo.fim.getTime() - periodo.inicio.getTime();
    const fimAnt = new Date(periodo.inicio.getTime() - 1);
    const iniAnt = new Date(fimAnt.getTime() - dur);
    return { inicio: iniAnt, fim: fimAnt, label: `${iniAnt.toLocaleDateString('pt-BR')} até ${fimAnt.toLocaleDateString('pt-BR')}`, tipo: 'custom' };
  }
  return null;
}

// ── Preset de período reutilizável para outras telas (ex.: Faturas) ─────────
// Preenche os inputs de data (ini/fim) conforme o tipo e dispara o callback.
function aplicarPresetPeriodo(tipo, idIni, idFim, callback) {
  const ini = document.getElementById(idIni);
  const fim = document.getElementById(idFim);
  if (!ini || !fim) return;
  const toISO = d => d ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : '';
  if (!tipo || tipo === 'custom') { if (typeof callback === 'function') callback(); return; }
  const per = calcularPeriodoPadrao(tipo);
  ini.value = toISO(per.inicio);
  fim.value = toISO(per.fim);
  if (typeof callback === 'function') callback();
}

function dataDentroDashboardPeriodo(dateLike, periodo = getDashboardPeriodo()) {
  const d = parseDataDashboard(dateLike);
  if (!d) return false;
  if (periodo.inicio && d < periodo.inicio) return false;
  if (periodo.fim && d > periodo.fim) return false;
  return true;
}

function setDashboardPeriodo(tipo) {
  dashboardPeriodoTipo = tipo || 'current_month';
  localStorage.setItem('evcore_dashboard_periodo_tipo', dashboardPeriodoTipo);
  updateDashboard();
}

function setDashboardPeriodoCustom() {
  dashboardPeriodoTipo = 'custom';
  dashboardPeriodoCustomStart = document.getElementById('dash-period-start')?.value || '';
  dashboardPeriodoCustomEnd = document.getElementById('dash-period-end')?.value || '';
  localStorage.setItem('evcore_dashboard_periodo_tipo', dashboardPeriodoTipo);
  localStorage.setItem('evcore_dashboard_periodo_inicio', dashboardPeriodoCustomStart);
  localStorage.setItem('evcore_dashboard_periodo_fim', dashboardPeriodoCustomEnd);
  updateDashboard();
}

function valorBrutoRecarga(r) {
  if (!r) return 0;
  return Number(r.cobranca ?? r.total ?? r.valorTotal ?? r.valor ?? 0) || 0;
}

function valorReceitaDashboard(r) {
  if (!r) return 0;
  const bruto = valorBrutoRecarga(r);
  // Recarga livre só entra como faturamento se foi vinculada/faturada manualmente.
  if (r.tipoOperacao === 'recarga_livre' && !r.faturamentoManual && !r.faturaId) return 0;
  return bruto;
}

function valorRecarga(r) {
  return valorReceitaDashboard(r);
}

function valorFatura(f) {
  return Number(f?.totalPagar ?? f?.valor ?? 0) || 0;
}

function formatMoneyDash(v) {
  const n = Number(v || 0);
  if (Math.abs(n) >= 1000000) return 'R$' + (n / 1000000).toFixed(1).replace('.', ',') + ' mi';
  if (Math.abs(n) >= 1000) return 'R$' + (n / 1000).toFixed(1).replace('.', ',') + 'k';
  return 'R$' + n.toFixed(0).replace('.', ',');
}

function formatMoneyFull(v) {
  return 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
}

function getRecargasDashboard(periodo) {
  const vistas = new Set();
  return recargas.filter(r => {
    if (!r || recargaOculta(r) || r.tipoOperacao === 'sessao_cancelada') return false;
    if (r.fonte === 'report_exemplo.pdf' || String(r.id || '').startsWith('rec_s')) return false;
    if (!dataDentroDashboardPeriodo(r.data, periodo)) return false;
    const uid = r.uid || gerarRecargaUID(r);
    if (vistas.has(uid)) return false;
    vistas.add(uid);
    return true;
  });
}

function getFaturasDashboard(periodo) {
  return faturas.filter(f => dataDentroDashboardPeriodo(f.emitidaEm || f.dataEmissao || f.vencimento, periodo));
}

function calcularLucroRedeDashboard(recargasPeriodo) {
  const bruto = recargasPeriodo.reduce((s, r) => s + valorReceitaDashboard(r), 0);
  const descontosPosPago = recargasPeriodo.reduce((s, r) => s + descontoPosPagoDaRecarga(r), 0);
  // Cupons de desconto da Tupi (aplicados antes da cobrança — o faturamento já
  // vem líquido deles; aqui somamos só para exibição em "Descontos totais").
  const descontosCupons = recargasPeriodo.reduce((s, r) => s + (Number(r.valorCupom || 0) || 0), 0);
  const receitaLiquida = Math.max(0, bruto - descontosPosPago);

  // Taxa Tupi = custo nosso, somada recarga a recarga (taxa da estação —
  // multi-CNPJ, 8% ou 10% — sobre o bruto Tupi: valor cobrado + cupom).
  const taxaFinanceira = somaTaxaTupi(recargasPeriodo);
  let custoEnergia = 0;
  let comissaoParceiro = 0;
  let mensalidadeParceiros = 0;
  const recargasJaAlocadas = new Set();

  (parceiros || []).forEach(p => {
    const equipamentos = Array.isArray(p.equipamentos) ? p.equipamentos : [];
    const lista = recargasPeriodo.filter(r => equipamentos.includes(getEquipamentoRecarga(r)));
    if (!lista.length) return;

    lista.forEach(r => recargasJaAlocadas.add(r.uid || r.id || gerarRecargaUID(r)));
    const brutoParceiro       = lista.reduce((s, r) => s + valorReceitaDashboard(r), 0);
    const descontosParceiro   = lista.reduce((s, r) => s + descontoPosPagoDaRecarga(r), 0);
    const receitaParceiro     = Math.max(0, brutoParceiro - descontosParceiro);
    const kwhParceiro         = lista.reduce((s, r) => s + (Number(r.kwh || 0) || 0), 0);
    const custoParceiro       = kwhParceiro * Number(p.custoEnergia || 0);
    const mensalidade         = Number(p.mensalidade || 0);
    const taxaOpPct           = Number(p.taxaOperacional || 0);
    const taxaOp              = receitaParceiro * (taxaOpPct / 100);

    custoEnergia += custoParceiro;
    mensalidadeParceiros += mensalidade;

    // Mesma base do relatório de parceiro: receita líquida - energia - taxas operacionais - mensalidade.
    const lucroLiquidoParceiro = receitaParceiro - custoParceiro - taxaOp - mensalidade;
    const comissaoBruta = Math.max(0, lucroLiquidoParceiro) * (Number(p.comissao || 0) / 100);
    const compromissoMin = Number(p.compromisoMinimo || 0);
    comissaoParceiro += compromissoMin > 0 ? Math.max(comissaoBruta, compromissoMin) : comissaoBruta;
  });

  recargasPeriodo.forEach(r => {
    const key = r.uid || r.id || gerarRecargaUID(r);
    if (!recargasJaAlocadas.has(key)) custoEnergia += Number(r.custo || 0);
  });

  // Mensalidades de parceiros são receita da rede, não custo.
  const receitaTotalRede = receitaLiquida + mensalidadeParceiros;
  const lucroRede = receitaTotalRede - custoEnergia - taxaFinanceira - comissaoParceiro;
  return { bruto, descontosPosPago, descontosCupons, receitaLiquida, receitaTotalRede, custoEnergia, taxaFinanceira, comissaoParceiro, mensalidadeParceiros, lucroRede };
}

function getClienteKeyDashboard(r) {
  const c = r?.clienteId ? clientes.find(x => x.id === r.clienteId) : clientePorRFID(r?.rfid);
  if (c?.id) return `cadastro:${c.id}`;
  const rfid = normalizarRFID(r?.rfid || '');
  if (rfid) return `rfid:${rfid}`;
  const nome = normalizarTextoChave(r?.nomeCliente || r?.cliente || '');
  if (nome) return `nome:${nome}`;
  return null;
}

function getClienteNomeDashboard(r) {
  const c = r?.clienteId ? clientes.find(x => x.id === r.clienteId) : clientePorRFID(r?.rfid);
  return c?.nome || r?.nomeCliente || r?.cliente || 'Sem identificação';
}

function getClienteRfidDashboard(r) {
  const c = r?.clienteId ? clientes.find(x => x.id === r.clienteId) : clientePorRFID(r?.rfid);
  return c?.rfid || r?.rfid || '';
}

function isClientePosPagoDashboard(r) {
  const c = r?.clienteId ? clientes.find(x => x.id === r.clienteId) : clientePorRFID(r?.rfid);
  return c?.tipo === 'pos' || r?.tipoCobranca === 'pos' || r?.tipoOperacao === 'pos_pago';
}

function formatKwhDash(v) {
  return Number(v || 0).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + ' kWh';
}

function atualizarControlesPeriodoDashboard(periodo) {
  const tipoEl = document.getElementById('dash-period-type');
  const iniEl = document.getElementById('dash-period-start');
  const fimEl = document.getElementById('dash-period-end');
  if (tipoEl) tipoEl.value = dashboardPeriodoTipo;
  if (iniEl) {
    iniEl.style.display = dashboardPeriodoTipo === 'custom' ? 'block' : 'none';
    iniEl.value = dashboardPeriodoCustomStart;
  }
  if (fimEl) {
    fimEl.style.display = dashboardPeriodoTipo === 'custom' ? 'block' : 'none';
    fimEl.value = dashboardPeriodoCustomEnd;
  }
  const sub = document.getElementById('dashboard-subtitle');
  if (sub) sub.textContent = `${periodo.label} — Rede: ${getRedeConfig().nomeRede || 'EV Parking'}`;
}

function updateDashboard() {
  classificarRecargasPorCliente(recargas);
  const periodo = getDashboardPeriodo();
  atualizarControlesPeriodoDashboard(periodo);

  const recargasPeriodo = getRecargasDashboard(periodo);
  const faturasPeriodo = getFaturasDashboard(periodo);
  const clientesComRecarga = new Set();
  const clientesPosComRecarga = new Set();
  recargasPeriodo.forEach(r => {
    const key = getClienteKeyDashboard(r);
    if (!key) return;
    clientesComRecarga.add(key);
    if (isClientePosPagoDashboard(r)) clientesPosComRecarga.add(key);
  });

  const totalKwh = recargasPeriodo.reduce((s, r) => s + (Number(r.kwh || 0) || 0), 0);
  const financeiro = calcularLucroRedeDashboard(recargasPeriodo);
  const ticketMedio = recargasPeriodo.length ? financeiro.bruto / recargasPeriodo.length : 0;

  const setTxt = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
  // Despesas = Faturamento − Lucro da Rede (tudo que saiu entre um e outro:
  // energia, taxa Tupi, comissões, descontos — menos mensalidades, que são receita).
  const despesas = financeiro.bruto - financeiro.lucroRede;
  setTxt('stat-clientes-total', clientes.length);
  setTxt('stat-kwh-total', formatKwhDash(totalKwh));
  setTxt('stat-faturamento-bruto', moneyBR(financeiro.bruto));
  setTxt('stat-despesas', moneyBR(despesas));
  setTxt('stat-lucro-rede', moneyBR(financeiro.lucroRede));

  // ── Comparação com o período anterior equivalente ──
  const periodoAnterior = getDashboardPeriodoAnterior(periodo);
  const compRow = document.getElementById('dash-comparacao-row');
  if (compRow) compRow.style.display = periodoAnterior ? '' : 'none';
  if (periodoAnterior) {
    const recAnt = getRecargasDashboard(periodoAnterior);
    const finAnt = calcularLucroRedeDashboard(recAnt);
    const kwhAnt = recAnt.reduce((s, r) => s + (Number(r.kwh || 0) || 0), 0);
    const despAnt = finAnt.bruto - finAnt.lucroRede;

    const tituloComp = document.getElementById('dash-comparacao-titulo');
    if (tituloComp) tituloComp.textContent = `Período anterior — ${periodoAnterior.label}`;

    // % de variação do período ATUAL em relação ao anterior.
    // maiorMelhor=false para despesas (aumento = ruim, fica vermelho).
    const setDiff = (id, atual, anterior, maiorMelhor = true) => {
      const el = document.getElementById(id);
      if (!el) return;
      if (!(Math.abs(anterior) > 0.004)) { el.textContent = '—'; el.style.color = 'var(--text3)'; return; }
      const pct = ((atual - anterior) / Math.abs(anterior)) * 100;
      const seta = pct >= 0 ? '▲' : '▼';
      const positivo = maiorMelhor ? pct >= 0 : pct <= 0;
      el.textContent = `${seta} ${Math.abs(pct).toFixed(1).replace('.', ',')}% vs atual`;
      el.style.color = positivo ? 'var(--accent)' : 'var(--red)';
    };
    setTxt('stat-comp-kwh', formatKwhDash(kwhAnt));
    setTxt('stat-comp-faturamento', moneyBR(finAnt.bruto));
    setTxt('stat-comp-despesas', moneyBR(despAnt));
    setTxt('stat-comp-lucro', moneyBR(finAnt.lucroRede));
    setDiff('stat-comp-kwh-diff', totalKwh, kwhAnt, true);
    setDiff('stat-comp-faturamento-diff', financeiro.bruto, finAnt.bruto, true);
    setDiff('stat-comp-despesas-diff', despesas, despAnt, false);
    setDiff('stat-comp-lucro-diff', financeiro.lucroRede, finAnt.lucroRede, true);
    // Guardar para o PDF
    window.__dashComparacao = { periodoAnterior, kwhAnt, finAnt, despAnt };
  } else {
    window.__dashComparacao = null;
  }

  const ranking = new Map();
  recargasPeriodo.forEach(r => {
    const key = getClienteKeyDashboard(r) || normalizarTextoChave(r.nomeCliente || r.rfid || 'sem identificacao');
    const atual = ranking.get(key) || { nome: getClienteNomeDashboard(r), rfid: getClienteRfidDashboard(r), valor: 0, kwh: 0, recargas: 0 };
    atual.valor += valorRecarga(r);
    atual.kwh += Number(r.kwh || 0) || 0;
    atual.recargas += 1;
    ranking.set(key, atual);
  });

  const rankingLista = [...ranking.values()].sort((a, b) => b.valor - a.valor).slice(0, 7);
  const rankingWrap = document.getElementById('dash-ranking-clientes');
  const rankingCount = document.getElementById('ranking-clientes-count');
  if (rankingCount) rankingCount.textContent = rankingLista.length ? `${rankingLista.length} cliente(s)` : '';
  if (rankingWrap) {
    if (!rankingLista.length) {
      rankingWrap.innerHTML = `<div class="empty-state" style="padding:32px"><div class="empty-icon">🏆</div><div class="empty-title">Nenhum consumo no período</div><div class="empty-sub">Importe relatórios para visualizar o ranking</div></div>`;
    } else {
      rankingWrap.innerHTML = rankingLista.map((item, idx) => `
        <div class="client-mini" style="align-items:center">
          <div class="avatar ${idx < 3 ? 'avatar-green' : 'avatar-blue'}">${idx + 1}</div>
          <div class="client-mini-info">
            <div class="client-mini-name">${escapeHtml(item.nome)}</div>
            <div class="client-mini-detail">${escapeHtml(item.rfid || '—')} · ${item.recargas} recarga(s) · ${item.kwh.toFixed(2).replace('.', ',')} kWh</div>
          </div>
          <span class="mono" style="font-weight:800;color:var(--accent)">${formatMoneyFull(item.valor)}</span>
        </div>
      `).join('');
    }
  }



  const rankingEstacoes = new Map();
  recargasPeriodo.forEach(r => {
    const nome = getEquipamentoRecarga(r) || 'Estação não identificada';
    const atual = rankingEstacoes.get(nome) || { nome, valor: 0, kwh: 0, recargas: 0 };
    atual.valor += valorReceitaDashboard(r);
    atual.kwh += Number(r.kwh || 0) || 0;
    atual.recargas += 1;
    rankingEstacoes.set(nome, atual);
  });
  const rankingEstacoesLista = [...rankingEstacoes.values()].sort((a,b) => b.valor - a.valor).slice(0, 7);
  const estWrap = document.getElementById('dash-ranking-estacoes');
  const estCount = document.getElementById('ranking-estacoes-count');
  if (estCount) estCount.textContent = rankingEstacoesLista.length ? `${rankingEstacoesLista.length} estação(ões)` : '';
  if (estWrap) {
    if (!rankingEstacoesLista.length) {
      estWrap.innerHTML = `<div class="empty-state" style="padding:32px"><div class="empty-icon">⚡</div><div class="empty-title">Nenhuma estação no período</div><div class="empty-sub">Importe relatórios para visualizar o ranking</div></div>`;
    } else {
      estWrap.innerHTML = rankingEstacoesLista.map((item, idx) => `
        <div class="client-mini" style="align-items:center">
          <div class="avatar ${idx < 3 ? 'avatar-green' : 'avatar-blue'}">${idx + 1}</div>
          <div class="client-mini-info">
            <div class="client-mini-name">${escapeHtml(item.nome)}</div>
            <div class="client-mini-detail">${item.recargas} recarga(s) · ${item.kwh.toFixed(2).replace('.', ',')} kWh</div>
          </div>
          <span class="mono" style="font-weight:800;color:var(--accent)">${formatMoneyFull(item.valor)}</span>
        </div>
      `).join('');
    }
  }

  // % sobre a receita total da rede (base de margem/markup)
  const pctReceita = v => financeiro.receitaTotalRede > 0.004
    ? (v / financeiro.receitaTotalRede * 100).toFixed(1).replace('.', ',') + '%'
    : '—';

  const resumo = document.getElementById('dash-resumo-periodo');
  if (resumo) {
    resumo.innerHTML = `
      <div class="parse-result-item"><span class="parse-key">Recargas no período</span><span class="parse-value">${recargasPeriodo.length}</span></div>
      <div class="parse-result-item"><span class="parse-key">Ticket médio por recarga</span><span class="parse-value">${formatMoneyFull(ticketMedio)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Clientes únicos com consumo</span><span class="parse-value">${clientesComRecarga.size}</span></div>
      <div class="parse-result-item"><span class="parse-key">Descontos totais <span style="color:var(--text3);font-size:11px">(pós-pagos + cupons Tupi)</span></span><span class="parse-value">${formatMoneyFull(financeiro.descontosPosPago + financeiro.descontosCupons)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Receita líquida real</span><span class="parse-value">${formatMoneyFull(financeiro.receitaLiquida)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Custo energia estimado</span><span class="parse-value">${formatMoneyFull(financeiro.custoEnergia)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Taxa plataforma Tupi</span><span class="parse-value">${formatMoneyFull(financeiro.taxaFinanceira)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Comissão parceiros</span><span class="parse-value">${formatMoneyFull(financeiro.comissaoParceiro)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Mensalidades parceiros (receita)</span><span class="parse-value">${formatMoneyFull(financeiro.mensalidadeParceiros)}</span></div>
      <div class="parse-result-item"><span class="parse-key">Receita total da rede</span><span class="parse-value">${formatMoneyFull(financeiro.receitaTotalRede)} <span style="color:var(--text3);font-size:11px">· 100%</span></span></div>
      <div class="parse-result-item"><span class="parse-key">Despesas totais</span><span class="parse-value">${formatMoneyFull(financeiro.receitaTotalRede - financeiro.lucroRede)} <span style="color:var(--text3);font-size:11px">· ${pctReceita(financeiro.receitaTotalRede - financeiro.lucroRede)}</span></span></div>
      <div class="parse-result-item" style="border-color:rgba(0,229,160,0.35);background:var(--accent-dim)"><span class="parse-key" style="color:var(--accent)">Lucro da Rede <span style="font-size:11px;opacity:0.8">(margem ${pctReceita(financeiro.lucroRede)})</span></span><span class="parse-value" style="color:var(--accent)">${formatMoneyFull(financeiro.lucroRede)}</span></div>
    `;
  }

  // Dados para o exportador de PDF do dashboard
  window.__dashPDF = {
    periodo, financeiro, totalKwh, despesas,
    recargasQtd: recargasPeriodo.length,
    ticketMedio,
    clientesUnicos: clientesComRecarga.size
  };
}

// ── 9) Exportar resumo do dashboard em PDF ──────────────────────────────────
function exportarDashboardPDF() {
  const d = window.__dashPDF;
  if (!d) { toast('Abra o dashboard antes de exportar.', 'error'); return; }
  const JsPDFCtor = window.jspdf?.jsPDF || window.jsPDF;
  if (!JsPDFCtor) { toast('Biblioteca de PDF não carregada.', 'error'); return; }

  const doc = new JsPDFCtor({ unit: 'pt', format: 'a4' });
  const W = doc.internal.pageSize.getWidth();
  const M = 48;
  let y = 56;
  const rede = getRedeConfig().nomeRede || 'EV Parking';
  const money = v => 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  doc.setFont('helvetica', 'bold'); doc.setFontSize(16);
  doc.text(`Dashboard — ${rede}`, M, y); y += 20;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(110);
  doc.text(`Período: ${d.periodo.label} · Gerado em ${new Date().toLocaleString('pt-BR')}`, M, y); y += 26;
  doc.setTextColor(0);

  const linha = (chave, valor, destaque = false) => {
    if (destaque) { doc.setFont('helvetica', 'bold'); } else { doc.setFont('helvetica', 'normal'); }
    doc.setFontSize(11);
    doc.text(chave, M, y);
    doc.text(String(valor), W - M, y, { align: 'right' });
    y += 18;
  };
  const secao = (titulo) => {
    y += 8;
    doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
    doc.text(titulo, M, y); y += 6;
    doc.setDrawColor(200); doc.line(M, y, W - M, y); y += 14;
  };

  secao('Indicadores do período');
  linha('Recargas no período', d.recargasQtd);
  linha('Clientes únicos com consumo', d.clientesUnicos);
  linha('Energia total', Number(d.totalKwh || 0).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + ' kWh');
  linha('Ticket médio por recarga', money(d.ticketMedio));
  linha('Faturamento', money(d.financeiro.bruto), true);
  linha('Despesas', money(d.despesas), true);
  linha('Lucro da Rede', money(d.financeiro.lucroRede), true);

  secao('Detalhamento financeiro');
  const pctRec = v => d.financeiro.receitaTotalRede > 0.004
    ? ' (' + (v / d.financeiro.receitaTotalRede * 100).toFixed(1).replace('.', ',') + '%)'
    : '';
  linha('Descontos totais (pós-pagos + cupons Tupi)', money((d.financeiro.descontosPosPago || 0) + (d.financeiro.descontosCupons || 0)));
  linha('Receita líquida real', money(d.financeiro.receitaLiquida));
  linha('Custo energia estimado', money(d.financeiro.custoEnergia));
  linha('Taxa plataforma Tupi', money(d.financeiro.taxaFinanceira));
  linha('Comissão parceiros', money(d.financeiro.comissaoParceiro));
  linha('Mensalidades parceiros (receita)', money(d.financeiro.mensalidadeParceiros));
  linha('Receita total da rede', money(d.financeiro.receitaTotalRede) + ' (100%)');
  linha('Despesas totais', money(d.financeiro.receitaTotalRede - d.financeiro.lucroRede) + pctRec(d.financeiro.receitaTotalRede - d.financeiro.lucroRede));
  linha('Lucro da Rede', money(d.financeiro.lucroRede) + pctRec(d.financeiro.lucroRede), true);

  const comp = window.__dashComparacao;
  if (comp) {
    const pct = (a, b) => Math.abs(b) > 0.004 ? ((a - b) / Math.abs(b) * 100) : null;
    const fmtPct = v => v == null ? '—' : (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(1).replace('.', ',') + '%';
    secao(`Comparação com o período anterior (${comp.periodoAnterior.label})`);
    linha('Energia total (anterior)', Number(comp.kwhAnt || 0).toLocaleString('pt-BR', { maximumFractionDigits: 2 }) + ' kWh  ·  ' + fmtPct(pct(d.totalKwh, comp.kwhAnt)));
    linha('Faturamento (anterior)', money(comp.finAnt.bruto) + '  ·  ' + fmtPct(pct(d.financeiro.bruto, comp.finAnt.bruto)));
    linha('Despesas (anterior)', money(comp.despAnt) + '  ·  ' + fmtPct(pct(d.despesas, comp.despAnt)));
    linha('Lucro da Rede (anterior)', money(comp.finAnt.lucroRede) + '  ·  ' + fmtPct(pct(d.financeiro.lucroRede, comp.finAnt.lucroRede)));
  }

  doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(130);
  doc.text('Gerado automaticamente pelo EV Core.', M, doc.internal.pageSize.getHeight() - 32);

  const nomeArq = `dashboard_${d.periodo.label.replace(/[^\w\d]+/g, '_').toLowerCase()}.pdf`;
  doc.save(nomeArq);
  toast('PDF do dashboard exportado!', 'success');
}


function estacaoCadastradaParaRecarga(r) {
  const eq = normalizarTextoChave(getEquipamentoRecarga(r) || r.local || r.equipamento || '');
  if (!eq) return true;
  return (estacoes || []).some(e => {
    const nomes = [e.nome, e.nomeCorreto, e.equipamento, e.idTupi, e.id, e.local].filter(Boolean).map(normalizarTextoChave);
    return nomes.some(n => n && (eq.includes(n) || n.includes(eq)));
  });
}

function detectarDivergenciasTupi(novas = []) {
  const alertas = [];
  (novas || []).forEach(n => {
    const uid = n.uid || gerarRecargaUID(n);
    const antiga = recargas.find(r => r !== n && (r.uid === uid || gerarRecargaUID(r) === uid));
    if (antiga) {
      const diffs = [];
      if (Math.abs(Number(antiga.kwh || 0) - Number(n.kwh || 0)) > 0.02) diffs.push('kWh');
      if (Math.abs(valorBrutoRecarga(antiga) - valorBrutoRecarga(n)) > 0.02) diffs.push('valor');
      if (normalizarTextoChave(getEquipamentoRecarga(antiga)) !== normalizarTextoChave(getEquipamentoRecarga(n))) diffs.push('estação');
      if (diffs.length) alertas.push({ tipo: 'duplicidade_divergente', nivel: 'erro', titulo: 'Recarga já existente com dados diferentes', detalhe: `${n.data || 'sem data'} · ${getEquipamentoRecarga(n)} · divergência em ${diffs.join(', ')}` });
    }
    if (!estacaoCadastradaParaRecarga(n)) {
      alertas.push({ tipo: 'estacao_nao_cadastrada', nivel: 'aviso', titulo: 'Estação nova/não cadastrada', detalhe: `${getEquipamentoRecarga(n)} · ${n.data || ''}` });
    }
    if (Number(n.kwh || 0) > 0 && valorBrutoRecarga(n) <= 0 && n.tipoOperacao !== 'recarga_livre') {
      alertas.push({ tipo: 'valor_zerado', nivel: 'aviso', titulo: 'Recarga com kWh e valor zerado', detalhe: `${n.data || ''} · ${getEquipamentoRecarga(n)} · ${Number(n.kwh || 0).toFixed(2)} kWh` });
    }
  });
  const existentes = JSON.parse(localStorage.getItem('evcore_alertas_divergencia_tupi') || '[]');
  const todos = [...alertas, ...existentes].slice(0, 80);
  localStorage.setItem('evcore_alertas_divergencia_tupi', JSON.stringify(todos));
  renderAlertasDivergenciaTupi();
  return alertas;
}

function renderAlertasDivergenciaTupi() {
  const el = document.getElementById('tupi-divergencias-alertas');
  if (!el) return;
  const alertas = JSON.parse(localStorage.getItem('evcore_alertas_divergencia_tupi') || '[]');
  if (!alertas.length) {
    el.innerHTML = `<div class="card" style="border-color:rgba(0,229,160,0.18);padding:14px 16px"><div style="font-size:13px;color:var(--text2)">✅ Nenhuma divergência Tupi x sistema registrada nas últimas importações.</div></div>`;
    return;
  }
  const erros = alertas.filter(a => a.nivel === 'erro').length;
  el.innerHTML = `<div class="card" style="border-color:${erros ? 'rgba(239,68,68,0.45)' : 'rgba(245,158,11,0.45)'};margin-bottom:16px">
    <div class="card-header"><div><div class="card-title">⚠️ Alertas de divergência Tupi x sistema</div><div style="font-size:12px;color:var(--text2);margin-top:3px">${alertas.length} alerta(s) nas últimas importações · ${erros} crítico(s)</div></div><button class="btn btn-secondary btn-sm" onclick="limparAlertasDivergenciaTupi()">Limpar alertas</button></div>
    <div style="display:flex;flex-direction:column;gap:8px;margin-top:10px;max-height:220px;overflow:auto">
      ${alertas.slice(0,12).map(a => `<div style="background:var(--surface2);border:1px solid ${a.nivel === 'erro' ? 'rgba(239,68,68,0.35)' : 'rgba(245,158,11,0.35)'};border-radius:8px;padding:10px 12px"><div style="font-weight:700;color:${a.nivel === 'erro' ? 'var(--red)' : 'var(--yellow)'};font-size:13px">${escapeHtml(a.titulo)}</div><div style="font-size:12px;color:var(--text2);margin-top:2px">${escapeHtml(a.detalhe)}</div></div>`).join('')}
    </div>
  </div>`;
}
function limparAlertasDivergenciaTupi() { localStorage.removeItem('evcore_alertas_divergencia_tupi'); renderAlertasDivergenciaTupi(); }

