async function logoutSistema() {
  if (!confirm('Deseja sair do sistema?')) return;
  try {
    await fetch('/api/logout', { method: 'POST' });
  } catch (err) {
    console.warn('Erro ao sair:', err);
  }
  window.location.href = '/login';
}

function closeModal(id) {
  document.getElementById(id).classList.remove('open');
  // restore save button
  if (id === 'modal-fatura') {
    document.querySelector('#modal-fatura .modal-actions').innerHTML = `
      <button class="btn btn-secondary" onclick="closeModal('modal-fatura')">Fechar</button>
      <button class="btn btn-primary" onclick="salvarFaturaGerada()">💾 Salvar Fatura</button>
    `;
  }
}

function toast(msg, type = 'success') {
  const container = document.getElementById('toast-container');
  const el = document.createElement('div');
  el.className = `toast toast-${type}`;
  el.innerHTML = `${type === 'success' ? '✅' : '❌'} ${msg}`;
  container.appendChild(el);
  setTimeout(() => el.remove(), 3500);
}

// Close modals on overlay click
document.querySelectorAll('.modal-overlay').forEach(o => {
  o.addEventListener('click', e => { if (e.target === o) closeModal(o.id); });
});

// Init
garantirModalConfigRede();
updateDashboard();
// Carrega do servidor e, em seguida, importa automaticamente as recargas da API.
// Depois, revalida a cada 30 minutos enquanto o app estiver aberto (sem botão).
loadState().then(() => {
  importarRecargasAPI({ silencioso: true });
  setInterval(() => importarRecargasAPI({ silencioso: true }), 30 * 60 * 1000);
});

// ── CONFIG PIX
function openConfigPix() {
  const current = localStorage.getItem('evparking_pix_api_base') || PIX_API_BASE || window.location.origin;
  const url = prompt('URL do backend Pix da Rede:', current);
  if (url !== null) {
    localStorage.setItem('evparking_pix_api_base', url.trim() || '');
    toast('URL do backend Pix salva! Recarregue a página para aplicar.', 'success');
  }
}
